  ui_story_5009_50090201_97_dialog_content = "Permítame intervenir. La situación específica debe ser—",
  ui_story_5009_50090201_98_dialog_content = "Te has pasado de la raya, Pittman.",
  ui_story_5009_50090201_99_dialog_content = "Perdóneme por ser grosero, Su Alteza.",
  ui_story_5009_50090201_100_dialog_content = "Solo deseo divulgar la información más actualizada.",
  ui_story_5009_50090201_101_dialog_content = "¿Quién es ese, Carleen?",
