  ui_story_5009_50090201_103_dialog_content = "¿Verdad?",
  ui_story_5009_50090201_104_dialog_content = "Cómo estás, PlayerName. Tu reputación te precede. Soy el investigador Wayne Pittman, de Lumópolis.",
  ui_story_5009_50090201_105_dialog_content = "Volvamos al asunto.",
  ui_story_5009_50090201_106_dialog_content = "Iré directo al grano entonces. Además de los que huyen de Dunefire Line, los eclipses de otras áreas también convergen en Eraveil.",
  ui_story_5009_50090201_107_dialog_content = "Se dice que los Eclipsites de Dunefire se adaptaron en términos de habilidades y tácticas.",
  ui_story_5009_50090201_108_dialog_content = "Me preocupa que tengan la intención de lanzar una ofensiva igualmente importante en Eraveil, de ahí la razón por la que estoy aquí.",
