  ui_story_5009_50090301_5_dialog_content = "¡Sí!",
  ui_story_5009_50090301_6_dialog_content = "¡Entonces movámonos de acuerdo con el plan y comencemos a limpiar los Eclipsites!",
  ui_story_5009_50090301_7_dialog_content = "¡A la carga!",
  ui_story_5009_50090301_8_dialog_content = "Ahí van... ¡Parecen estar aún más entusiasmados que yo!",
  ui_story_5009_50090301_9_dialog_content = "El entusiasmo es nuestra ventaja, la de los soldados de Illumina, en la batalla. Ten la seguridad de que llevarán a cabo la operación.",
  ui_story_5009_50090301_10_dialog_content = "Podemos ir al puesto ahora mismo.",
  ui_story_5009_50090301_11_dialog_content = "Hablando de eso, ¿hacia dónde vamos? PlayerName?",
  ui_story_5009_50090301_12_dialog_content = "Uh... Yo tampoco estoy seguro.",
  ui_story_5009_50090301_13_dialog_content = "Permíteme consultar mi guía de misión. Ah, dice...",
  ui_story_5009_50090301_14_dialog_content = "El puesto de Unión de Mensajería se ubica en la torre blanca gigante en el noreste de Eraveil.",
  ui_story_5009_50090301_15_dialog_content = "¿Cómo sabes eso, Sr. Pittman?",
  ui_story_5009_50090301_16_dialog_content = "He realizado investigaciones aquí antes y he leído muchos archivos sobre Eraveil.",
  ui_story_5009_50090301_17_dialog_content = "El noreste debería ser por aquí...",
