  ui_story_5009_50090301_26_dialog_content = "¿Qué? No lo entiendo.",
  ui_story_5009_50090301_27_dialog_content = "En pocas palabras, los Lins enterraron a tu gente y dejaron las lápidas.",
  ui_story_5009_50090301_28_dialog_content = "Son uno de los gremios más famosos del mundo. Vice y Carleen, ustedes dos deben conocerlos.",
  ui_story_5009_50090301_29_dialog_content = "Sí, también sé que los Lin estaban en buenos términos con los Caelestites y Northland.",
  ui_story_5009_50090301_30_dialog_content = "Parece que Naroxel tiene razón en que los Lin enterraron a los muertos de Eraveil de acuerdo con sus costumbres.",
  ui_story_5009_50090301_31_dialog_content = "Para los Celestitas, descansar en la tierra representa un regreso a la naturaleza, de la que seremos parte después de la muerte.",
  ui_story_5009_50090301_32_dialog_content = "El Gremio Lin...",
  ui_story_5009_50090301_33_dialog_content = "Primero terminemos lo que vinimos a hacer aquí.",
  ui_story_5009_50090301_34_dialog_content = "Está bien.",
  ui_story_5009_50090302_1_dialog_content = "La emblemática torre blanca conocida como Faro Deepvalley ...",
  ui_story_5009_50090302_2_dialog_content = "no debe estar muy por delante.",
  ui_story_5009_50090302_3_dialog_content = "Nos dividiremos en dos grupos. Iré a encargarme de los Eclipsites con Vice y los demás. Te diriges al puesto.",
  ui_story_5009_50090302_4_dialog_content = "¡Okey! ¡Corro rápido, voy a ver!",
  ui_story_5009_50090302_5_dialog_content = "Y nos encargaremos de la reparación del correo.",
  ui_story_5009_50090302_6_dialog_content = "Te prometemos que verás un sitio completamente nuevo cuando regrese.",
  ui_story_5009_50090302_7_dialog_content = "Estoy segura. Gracias.",
  ui_story_5009_50090302_8_dialog_content = "Sigamos dirigiéndonos hacia el este y llevemos a los Eclipsites allí.",
  ui_story_5009_50090302_9_dialog_content = "Oh, tu presencia también es necesaria para una ceremonia.",
  ui_story_5009_50090302_10_dialog_content = "¿Qué ceremonia?",
  ui_story_5009_50090302_11_dialog_content = "No te preocupes, solo llevará unos minutos.",
  ui_story_5009_50090302_12_dialog_content = "Primero, debemos verificar su identidad. Aunque, por supuesto, eso ya se ha hecho.",
  ui_story_5009_50090302_13_dialog_content = "Entonces necesitamos que firmes dos documentos.",
  ui_story_5009_50090302_14_dialog_content = "El primero es el Acuerdo postal. Por favor fírmalo, luego firma el Permiso para Trabajar.",
  ui_story_5009_50090302_15_dialog_content = "Suena complicado... Déjame echar un vistazo más de cerca.",
  ui_story_5009_50090302_16_dialog_content = "¿Es realmente necesario hacer esto justo antes de la batalla?",
  ui_story_5009_50090302_17_dialog_content = "<color=#e8d9bb>Unos minutos más tarde...</color>",
  ui_story_5009_50090302_18_dialog_content = "Mis ojos están vidriosos... Lo firmaré ahora.",
  ui_story_5009_50090302_19_dialog_content = "Por último, tenemos un Documento de Verificación...",
  ui_story_5009_50090302_20_dialog_content = "¿Tengo que firmar esto también? ¡Vaya, otro largo!",
  ui_story_5009_50090302_21_dialog_content = "¡Solo fírmalo! La Unión es confiable, no te estafarán.",
  ui_story_5009_50090302_22_dialog_content = "Sin embargo, para documentos extraños de cualquier otra persona, ¡asegúrate de leerlos primero!",
  ui_story_5009_50090302_23_dialog_content = "Éste puede esperar hasta que se reconstruya el puesto.",
  ui_story_5009_50090302_24_dialog_content = "Además, después de llegar al puesto de la Torre Blanca...",
  ui_story_5009_50090302_25_dialog_content = "Enviaremos coordenadas a la Unión y proporcionaremos un informe de daños.",
  ui_story_5009_50090302_26_dialog_content = "La Unión enviará ayuda en consecuencia, por lo que podemos garantizar que se complete hoy.",
  ui_story_5009_50090302_27_dialog_content = "Espere con ansias las nuevas instalaciones.",
  ui_story_5009_50090302_28_dialog_content = "¡Nawoxel, encontré la Torre Blanca allí!",
  ui_story_5009_50090302_29_dialog_content = "Entonces nos pondremos en marcha.",
  ui_story_5009_50090302_30_dialog_content = "Buena pelea, PlayerName!",
  ui_story_5009_50090302_31_dialog_content = "¡Haré lo mejor que pueda!",
  ui_story_5009_50090302_32_dialog_content = "¡Nos desharemos de todas las Eclipsites de Eraveil!",
  ui_story_5009_50090401_1_dialog_content = "¡Objetivo localizado al noreste, mi señor!",
  ui_story_5009_50090401_2_dialog_content = "Mi mi. La encantadora princesa entra en el valle para encontrarse con su encantador caballero...",
  ui_story_5009_50090401_3_dialog_content = "¿Qué tipo de historia tonta es esta? ¡La odio!",
  ui_story_5009_50090401_4_dialog_content = "Bueno, ¡ha llegado nuestra oportunidad!",
  ui_story_5009_50090401_5_dialog_content = "Pero ahora mismo hay muchos Aurorianos en Eraveil...",
  ui_story_5009_50090401_6_dialog_content = "Hacer un movimiento... podría ser arriesgado.",
  ui_story_5009_50090401_7_dialog_content = "¿No crees que pueda vencerlos?",
  ui_story_5009_50090401_8_dialog_content = "¡Te voy a devorar por arruinar mi humor!",
  ui_story_5009_50090401_9_dialog_content = "¿M-Mi señor...?",
  ui_story_5009_50090401_10_dialog_content = "¡Jajaja! ¿Estás temblando?",
  ui_story_5009_50090401_11_dialog_content = "Te ahorraré este tiempo solo porque puedes hablar Universés.",
  ui_story_5009_50090401_12_dialog_content = "Pero, pero... el Celestita también está presente.",
  ui_story_5009_50090401_13_dialog_content = "Escuché que puede sentirnos usando habilidades psíquicas.",
  ui_story_5009_50090401_14_dialog_content = "¿Y qué?",
  ui_story_5009_50090401_15_dialog_content = "Sabes, también podría traerme ese Celestita para la cena.",
  ui_story_5009_50090401_16_dialog_content = "¡Soy un genio!",
  ui_story_5009_50090401_17_dialog_content = "¡Ve a notificar a los otros Eclipsites humildes y diles que se preparen!",
  ui_story_5009_50090401_18_dialog_content = "¿Cómo es tu capacidad psíquica, PlayerName?",
  ui_story_5009_50090401_19_dialog_content = "No diría que es muy poderoso, pero es más que adecuado.",
  ui_story_5009_50090401_20_dialog_content = "Puedo sentir la ubicación de Eclipsites desde la distancia y decir cuáles son especiales.",
  ui_story_5009_50090401_21_dialog_content = "¿Te importaría describir qué fue diferente acerca de los Eclipsites especiales que encontró en la Línea Dunefire?",
  ui_story_5009_50090401_22_dialog_content = "La mayoría de ellos eran del tipo promedio, solo que más feroces.",
  ui_story_5009_50090401_23_dialog_content = "Pero las élites que conocimos en Entrañas 13 eran muy inteligentes. Eran luchadores.",
  ui_story_5009_50090401_24_dialog_content = "Además, eran capaces de sondear en busca de aberturas y usar tormentas de arena para cubrirse.",
  ui_story_5009_50090401_25_dialog_content = "Sí, también noté las tormentas de arena.",
  ui_story_5009_50090401_26_dialog_content = "Según mis hallazgos, las tormentas de arena y los flujos de energía en Dunefire pueden no haber sido fenómenos naturales.",
  ui_story_5009_50090401_27_dialog_content = "Al menos, no del todo natural.",
  ui_story_5009_50090401_28_dialog_content = "¿Estás diciendo que los Eclipsites pueden controlar el clima ahora?",
  ui_story_5009_50090401_29_dialog_content = "Es solo mi suposición. Necesito más pruebas.",
  ui_story_5009_50090401_30_dialog_content = "Y hay algo aún más complicado.",
  ui_story_5009_50090401_31_dialog_content = "No hay tiempo para hablar ahora. Siento una gran turba Eclipsites por delante.",
  ui_story_5009_50090401_32_dialog_content = "Yo guiaré Repartiré el juicio apropiado...",
  ui_story_5009_50090401_33_dialog_content = "¡Y aniquilalos a todos!",
  ui_story_5009_50090502_1_dialog_content = "¡Todo claro aquí! Vayamos al siguiente lugar.",
  ui_story_5009_50090502_2_dialog_content = "Espera, ¡algo anda mal!",
  ui_story_5009_50090502_3_dialog_content = "¿Quién eres?",
  ui_story_5009_50090502_4_dialog_content = "¿Hablas Universés, Eclipsite?",
  ui_story_5009_50090502_5_dialog_content = "Debes ser la Nemesis de la que habló mi señor...",
  ui_story_5009_50090502_6_dialog_content = "Wow, ¿los eclipses también pueden decir tonterías ahora?",
  ui_story_5009_50090502_7_dialog_content = "Muchos minions esta vez... Parece que vino preparado.",
  ui_story_5009_50090502_8_dialog_content = "Esto va a ser divertido.",
  ui_story_5009_50090502_9_dialog_content = "¿Por qué estás mirando al vacío, PlayerName?",
  ui_story_5009_50090502_10_dialog_content = "¡Acabo de sentir una gran horda de eclipses convergiendo en el cementerio!",
  ui_story_5009_50090502_11_dialog_content = "¡Entonces tenemos que ir allí ahora mismo!",
  ui_story_5009_50090502_12_dialog_content = "No, ahora se han ido todos.",
  ui_story_5009_50090502_13_dialog_content = "¿Todo se fue?",
  ui_story_5009_50090502_14_dialog_content = "Acaba de suceder...",
  ui_story_5009_50090502_15_dialog_content = "Una poderosa energía se desató en el cementerio y luego los Eclipsites se fueron.",
  ui_story_5009_50090502_16_dialog_content = "Podía sentir que era el poder Aurorian...",
  ui_story_5009_50090502_17_dialog_content = "¿Ese Aurorian es un amigo... o un enemigo?",
  ui_story_5009_50090502_18_dialog_content = "Todavía no lo sé, ¡pero este auroriano puede ocultar sus fluctuaciones de energía!",
  ui_story_5009_50090502_19_dialog_content = "En este momento, no puedo sentir su presencia.",
  ui_story_5009_50090502_20_dialog_content = "¿Por qué se esconden...? ¿Podrían ser algún tipo de enemigo desconocido?",
  ui_story_5009_50090502_21_dialog_content = "Tenemos que ser cuidadosos...",
  ui_story_5009_50090602_1_dialog_content = "¿Puedes sentir algo, PlayerName?",
  ui_story_5009_50090602_2_dialog_content = "El mismo Aurorian de antes. Alguien muy poderoso...",
  ui_story_5009_50090602_3_dialog_content = "¿Podría ser Naroxel? Ella es poderosa.",
  ui_story_5009_50090602_4_dialog_content = "Solo traje a Pittman conmigo.",
  ui_story_5009_50090602_5_dialog_content = "Pero debes conocerlos.",
  ui_story_5009_50090602_6_dialog_content = "Como sospechaba, ese Aurorian no vino con ustedes.",
  ui_story_5009_50090602_7_dialog_content = "¿Deberíamos enviar a alguien para que lo revise?",
  ui_story_5009_50090602_8_dialog_content = "Eso no es necesario. Recuerdo que Naroxel mencionó que Unión de Mensajería enviaría a alguien.",
  ui_story_5009_50090602_9_dialog_content = "Tal vez sea un miembro de la Unión.",
  ui_story_5009_50090602_10_dialog_content = "¿De qué están discutiendo, soldados?",
  ui_story_5009_50090602_11_dialog_content = "Teniente Vice, estábamos hablando de cómo Eraveil luchó contra los Eclipsites en el pasado.",
  ui_story_5009_50090602_12_dialog_content = "Hay una línea Illumina impenetrable entre Eraveil y la antigua guarida de Eclipsite.",
  ui_story_5009_50090602_13_dialog_content = "El terreno difícil de Eraveil hace que sea fácil de defender y difícil de atacar para los enemigos.",
  ui_story_5009_50090602_14_dialog_content = "Pero los Celestitas no pueden luchar. ¿Qué pasó cuando tuvieron que defenderse de los Eclipsites?",
  ui_story_5009_50090602_15_dialog_content = "Podían sentir los movimientos de Eclipsite y planificar con anticipación.",
  ui_story_5009_50090602_16_dialog_content = "Illumina y Lumopolis a menudo enviaban representantes y provisiones a Eraveil.",
  ui_story_5009_50090602_17_dialog_content = "Sí, Eraveil es un hueso duro de roer.",
  ui_story_5009_50090602_18_dialog_content = "Pero una vez que lo rompes, está condenado.",
  ui_story_5009_50090602_19_dialog_content = "Seguro que conoces el resto.",
  ui_story_5009_50090602_20_dialog_content = "¿Cómo llegaron los Eclipsites a la línea Illumina y entraron en Eraveil?",
  ui_story_5009_50090602_21_dialog_content = "Había un traidor entre nosotros.",
  ui_story_5009_50090602_22_dialog_content = "Cuanto más invulnerable sea tu defensa, más fácilmente será desarmada por la traición.",
  ui_story_5009_50090602_23_dialog_content = "Y hubo un eclipse ese día, por lo que todos los sistemas de defensa fallaron.",
  ui_story_5009_50090701_1_dialog_content = "¿Soy yo o está muy oscuro de repente?",
  ui_story_5009_50090701_2_dialog_content = "Se supone que es de día, pero está oscuro como la noche.",
  ui_story_5009_50090701_3_dialog_content = "¿Un eclipse justo como menciono uno? ¿Cómo puede ser esto?",
  ui_story_5009_50090701_4_dialog_content = "Pero a juzgar por el halo rojo carmesí en el cielo, ¡eso es exactamente lo que es!",
  ui_story_5009_50090701_5_dialog_content = "Esto debe ser un fenómeno similar, ¡tiene que serlo!",
  ui_story_5009_50090701_6_dialog_content = "¡Cuidado, todos, siento una perturbación extraña!",
  ui_story_5009_50090701_7_dialog_content = "Eraveil, eclipse...",
  ui_story_5009_50090701_8_dialog_content = "¿Es este el destino inevitable de Caelestite?",
  ui_story_5009_50090701_9_dialog_content = "Mantenga la calma, PlayerName!",
  ui_story_5009_50090701_10_dialog_content = "Deja de pensar demasiado y concéntrate en el presente.",
  ui_story_5009_50090701_11_dialog_content = "Tienes razón. Ahora estoy bien.",
  ui_story_5009_50090701_12_dialog_content = "¿Pero podría ser la persona que sentí antes?",
  ui_story_5009_50090701_13_dialog_content = "¿El que tiene la habilidad de ocultarse?",
  ui_story_5009_50090701_14_dialog_content = "El cielo oscuro, la corona escarlata.",
  ui_story_5009_50090701_15_dialog_content = "Estás a punto de hacer un movimiento...",
  ui_story_5009_50090701_16_dialog_content = "Pero esta vez, ¡no te salvarás!",
  ui_story_5009_50090702_1_dialog_content = "¡¿Qué está pasando?!",
  ui_story_5009_50090702_2_dialog_content = "¡Gah!",
  ui_story_5009_50090702_3_dialog_content = "¡No entrar en pánico! ¡Mata al Eclipsite primero!",
  ui_story_5009_50090702_4_dialog_content = "De alguna manera... no puedo usar todo mi poder, Carleen...",
  ui_story_5009_50090702_5_dialog_content = "Me siento igual.",
  ui_story_5009_50090702_6_dialog_content = "Tú que tal, PlayerName?",
  ui_story_5009_50090702_7_dialog_content = "Estoy bien, es solo ...",
  ui_story_5009_50090702_8_dialog_content = "¿Sólo qué?",
  ui_story_5009_50090702_9_dialog_content = "Mi capacidad psíquica parece haberse debilitado. No puedo sentir lo que está pasando en la distancia.",
  ui_story_5009_50090702_10_dialog_content = "Nuestros Luminatics también están suprimidas.",
  ui_story_5009_50090702_11_dialog_content = "Si no me equivoco es por el eclipse.",
  ui_story_5009_50090702_12_dialog_content = "¡Mantente alerta, ten cuidado con las emboscadas de Eclipsites!",
  ui_story_5009_50090702_13_dialog_content = "Me preocupa el grupo del puesto... Déjame tratar de comunicarme con ellos.",
  ui_story_5009_50090702_14_dialog_content = "No puedo llegar a ellas en absoluto!",
  ui_story_5009_50090702_15_dialog_content = "Así que las comunicaciones también están caídas.",
  ui_story_5009_50090702_16_dialog_content = "¿Podemos reunirnos con Naroxel en el puesto?",
  ui_story_5009_50090702_17_dialog_content = "Guiaré el camino.",
  ui_story_5009_50090702_18_dialog_content = "No puedo sentir lo que está pasando desde esta distancia, me preocupa que los eclipses nos rodeen...",
  ui_story_5009_50090702_19_dialog_content = "Nosotros lo cubriremos, teniente Vice.",
  ui_story_5009_50090702_20_dialog_content = "Sí, cuento contigo.",
  ui_story_5009_50090702_21_dialog_content = "¡Vamos, PlayerName!",
  ui_story_5009_50090801_1_dialog_content = "¡Explosión entrante!",
  ui_story_5009_50090801_2_dialog_content = "¡Cuidado!",
  ui_story_5009_50090801_3_dialog_content = "¡Cuidado!",
  ui_story_5009_50090801_4_dialog_content = "Lástima que falló.",
  ui_story_5009_50090801_5_dialog_content = "¿Listo?",
  ui_story_5009_50090801_6_dialog_content = "Vengo a buscarte.",
  ui_story_5009_50090801_7_dialog_content = "¿Están todos bien?",
  ui_story_5009_50090801_8_dialog_content = "Estoy bien. Y tú, PlayerName?",
  ui_story_5009_50090801_9_dialog_content = "Estoy bien.",
  ui_story_5009_50090801_10_dialog_content = "En este punto ya estoy acostumbrado.",
  ui_story_5009_50090801_11_dialog_content = "¿Dónde estamos...?",
  ui_story_5009_50090801_12_dialog_content = "PlayerName, ¿sabías que existía un lugar tan extraño en Eraveil?",
  ui_story_5009_50090801_13_dialog_content = "No. Solo tengo esta extraña sensación de que mis habilidades psíquicas son ...",
  ui_story_5009_50090801_14_dialog_content = "¿Son que? ¿Estás herido?",
  ui_story_5009_50090801_15_dialog_content = "De nada. Es solo que... este sentimiento es difícil de describir, es como... como...",
  ui_story_5009_50090801_16_dialog_content = "¡Como si mi nariz estuviera llena!",
  ui_story_5009_50090801_17_dialog_content = "¡Ahora no es momento de bromas!",
  ui_story_5009_50090801_18_dialog_content = "Lo siento, pero así es como me siento.",
  ui_story_5009_50090801_19_dialog_content = "A diferencia de antes, no puedo usar mi poder en absoluto.",
  ui_story_5009_50090801_20_dialog_content = "Si no podemos confiar en las habilidades de PlayerName...",
  ui_story_5009_50090801_21_dialog_content = "Tendremos que tener mucho cuidado al pelear aquí.",
  ui_story_5009_50090801_22_dialog_content = "¡Cuidado, alteza!",
  ui_story_5009_50090801_23_dialog_content = "¡¡¡!!!",
  ui_story_5009_50090801_24_dialog_content = "Lástima, estuve tan cerca de atraparte ...",
  ui_story_5009_50090801_25_dialog_content = "Su alteza, Carleen.",
  ui_story_5009_50090801_26_dialog_content = "¿Quién eres?",
  ui_story_5009_50090801_27_dialog_content = "¡Me siento tan honrado de que me hayas preguntado por mi nombre!",
  ui_story_5009_50090801_28_dialog_content = "Yo soy...",
  ui_story_5009_50090801_A1_dialog_content = "Oh, parece que me he olvidado de quién soy.",
  ui_story_5009_50090801_29_dialog_content = "...",
  ui_story_5009_50090801_30_dialog_content = "¿Sin reacción?",
  ui_story_5009_50090801_31_dialog_content = "Deberías estar gritando, \"¿Qué tipo de broma es esta?\" o \"¡Dime quién eres!\" en la parte superior de sus pulmones en un momento como este.",
  ui_story_5009_50090801_32_dialog_content = "Que asqueroso",
  ui_story_5009_50090801_33_dialog_content = "Deja de perder el aliento, Carleen.",
  ui_story_5009_50090801_34_dialog_content = "¡Solo mátalo!",
  ui_story_5009_50090801_35_dialog_content = "Lo intenté, Vice, pero todavía no recupero mis poderes.",
  ui_story_5009_50090801_36_dialog_content = "No hay problema. ¡Nos ocuparemos de la lucha!",
  ui_story_5009_50090801_37_dialog_content = "Vice, Pittman, cúbranme.",
  ui_story_5009_50090801_38_dialog_content = "¿Vas a pelear conmigo?",
  ui_story_5009_50090801_39_dialog_content = "¡Oh, estoy tan emocionado!",
  ui_story_5009_50090801_40_dialog_content = "¡Ven, alteza Carleen!",
  ui_story_5009_50090801_41_dialog_content = "¡Flor de hielo!",
  ui_story_5009_50090801_42_dialog_content = "Mmm...",
  ui_story_5009_50090801_43_dialog_content = "¿Cómo es que no dolió ni un poco?",
  ui_story_5009_50090801_44_dialog_content = "¡Luchemos juntos, Carleen!",
  ui_story_5009_50090801_45_dialog_content = "Ah, este tipo de pelea...",
  ui_story_5009_50090801_46_dialog_content = "¡es tan feo!",
  ui_story_5009_50090801_47_dialog_content = "!",
  ui_story_5009_50090801_48_dialog_content = "Todos ustedes fueron derrotados tan fácilmente.",
  ui_story_5009_50090801_49_dialog_content = "¡No eres rival para mí en lo más mínimo!",
  ui_story_5009_50090801_50_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_5009_50090801_51_dialog_content = "Shh, no interrumpas. Me decepcionas, Carleen.",
  ui_story_5009_50090801_52_dialog_content = "La forma en que peleaste fue fea e inadecuada para una princesa.",
  ui_story_5009_50090801_53_dialog_content = "Te iba a enmarcar como un cuadro hermoso, pero ahora he perdido todo interés.",
  ui_story_5009_50090801_54_dialog_content = "Todo es culpa tuya por arruinar la visión de Gautier.",
  ui_story_5009_50090801_55_dialog_content = "¿Gautier? ¿El apellido que fue borrado de los registros?",
  ui_story_5009_50090801_56_dialog_content = "Aparte de Beryl Gautier, solo hay...",
  ui_story_5009_50090801_57_dialog_content = "¡Debes ser Mirren Gautier!",
  ui_story_5009_50090801_58_dialog_content = "Vaya, ¿alguien aquí me reconoce?",
  ui_story_5009_50090801_59_dialog_content = "Estuviste en mi lista negra durante mucho tiempo. No esperaba que hoy fuera el día en que finalmente me encontraría contigo.",
  ui_story_5009_50090801_60_dialog_content = "¡Eres un refugiado y un traidor!",
  ui_story_5009_50090801_61_dialog_content = "¡No te preocupes tanto! ¡Al menos no sin antes agradecerme por anunciar mi nombre!",
  ui_story_5009_50090801_62_dialog_content = "Mirren... ¿Gautier?",
  ui_story_5009_50090801_63_dialog_content = "Si, su Alteza. Mirren Gautier, la mente maestra detrás de la insurrección de Pyrrhus y Gautier.",
  ui_story_5009_50090801_64_dialog_content = "¿Entonces es de Lumopolis?",
  ui_story_5009_50090801_65_dialog_content = "La forma en que se ve ahora, parece extraño incluso para los estándares de Eclipsite.",
  ui_story_5009_50090801_66_dialog_content = "Otro traidor de Lumopolis y Aurorian...",
  ui_story_5009_50090801_67_dialog_content = "¡Acepta tu juicio, Mirren Gautier!",
  ui_story_5009_50090801_68_dialog_content = "Espero que no estés bromeando.",
  ui_story_5009_50090801_69_dialog_content = "Lo detendré, tú ve a buscar una salida, PlayerName!",
  ui_story_5009_50090801_70_dialog_content = "todos siguen PlayerName. Cubriré la parte trasera.",
  ui_story_5009_50090801_71_dialog_content = "Dime, ¿a dónde vas?",
  ui_story_5009_50090801_72_dialog_content = "Fooey, se fueron...",
  ui_story_5009_50090801_73_dialog_content = "¡Acepta tu juicio, forajido!",
  ui_story_5009_50090801_74_dialog_content = "Sus intentos son inútiles. ¿Crees que ataques tan débiles tendrían algún efecto en mí?",
  ui_story_5009_50090801_75_dialog_content = "Esto es ridículo.",
  ui_story_5009_50090801_76_dialog_content = "He decidido hacerte sufrir hasta que mueras y luego hacerles lo mismo.",
  ui_story_5009_50090801_77_dialog_content = "Pero déjame ofrecerte un consejo amistoso primero...",
  ui_story_5009_50090801_78_dialog_content = "Ese inútil punk de Celestita nunca encontrará la salida de aquí.",
  ui_story_5009_50090801_79_dialog_content = "¡Este es el poder del Eclipse!",
  ui_story_5009_50090801_80_dialog_content = "Veo que tus piernas no son lo único que se estropeó durante el proceso de transformación...",
  ui_story_5009_50090801_81_dialog_content = "¡pero tus ojos y tu cabeza también!",
  ui_story_5009_50090801_82_dialog_content = "Jajajaja, bueno. ¡Tu cuerpo es el que se estropeará pronto!",
  ui_story_5009_50090801_83_dialog_content = "Vice, Carleen, creo que hemos llegado al final.",
  ui_story_5009_50090801_84_dialog_content = "Sí, puedo sentir una pared invisible.",
  ui_story_5009_50090801_85_dialog_content = "Quedarse a un lado, PlayerName.",
  ui_story_5009_50090801_86_dialog_content = "Golpea el mismo lugar conmigo, Vice.",
  ui_story_5009_50090801_87_dialog_content = "Roger! Torrente rápido!",
  ui_story_5009_50090801_88_dialog_content = "Claramente golpeamos, pero no hay señales de daño en absoluto.",
  ui_story_5009_50090801_89_dialog_content = "Busque cualquier cosa inusual cerca que pueda ser una salida.",
  ui_story_5009_50090801_90_dialog_content = "No, no visto ninguno.",
  ui_story_5009_50090801_91_dialog_content = "¿Existe realmente una salida en esta extraña dimensión?",
  ui_story_5009_50090801_92_dialog_content = "Rayos...",
  ui_story_5009_50090801_93_dialog_content = "Puedo sentir todo lo demás normalmente, incluso puedo escuchar el sonido de su pelea.",
  ui_story_5009_50090801_94_dialog_content = "¡Pero no puedo poner en marcha mi habilidad psíquica!",
  ui_story_5009_50090801_95_dialog_content = "Me temo que Pittman no durará mucho solo. Si las cosas siguen así ...",
  ui_story_5009_50090801_96_dialog_content = "Qué, ¿solo llegaste hasta aquí?",
  ui_story_5009_50090801_97_dialog_content = "¿Dónde está Pittman?",
  ui_story_5009_50090801_98_dialog_content = "¿Cómo se las arregla para detenerme con un intento tan débil?",
  ui_story_5009_50090801_99_dialog_content = "Oh, ahí está, cojeando de esta manera ahora mismo. ¿No es eso cómico?",
  ui_story_5009_50090801_100_dialog_content = "¡Estás herido, Pittman!",
  ui_story_5009_50090801_101_dialog_content = "Tos... Todavía puedo pelear... No te preocupes por mí...",
  ui_story_5009_50090801_102_dialog_content = "Muy bueno!",
  ui_story_5009_50090801_103_dialog_content = "Ahora, ¿continuamos el juego?",
  ui_story_5009_50090801_104_dialog_content = "¡Jaja!",
  ui_story_5009_50090901_1_dialog_content = "¡Seguimiento de Golpe!",
  ui_story_5009_50090901_2_dialog_content = "¿Ah? Oh, cuando se trata de ataques furtivos ...",
  ui_story_5009_50090901_3_dialog_content = "Realmente soy un experto.",
  ui_story_5009_50090901_4_dialog_content = "Oh...",
  ui_story_5009_50090901_5_dialog_content = "Mirren todavía podría usar Lumopolis Luminatics, ¿cómo puede ser esto?",
  ui_story_5009_50090901_6_dialog_content = "¿Cómo estás, Vice?",
  ui_story_5009_50090901_7_dialog_content = "¡Déjame intentarlo!",
  ui_story_5009_50090901_8_dialog_content = "Nunca digas eso hasta que puedas luchar mucho mejor que ellos.",
  ui_story_5009_50090901_9_dialog_content = "Ese es mi amable consejo para ti, Celestita.",
  ui_story_5009_50090901_10_dialog_content = "Tú iniciaste el eclipse y nos atrapaste en la dimensión de bolsillo...",
  ui_story_5009_50090901_11_dialog_content = "¡Oh, esas son las extraordinarias habilidades que Otorga el gran maestro, liberándome a mi propio destino!",
  ui_story_5009_50090901_12_dialog_content = "Bla, bla, bla. No es más que una transformación, y tampoco es nuevo para nosotros. Schummer, por ejemplo...",
  ui_story_5009_50090901_13_dialog_content = "Oh, eres divertido, pequeño Celestita.",
  ui_story_5009_50090901_14_dialog_content = "Mis estimados invitados Aurorian, ¿de verdad esperan que un Celestita los salve con palabras?",
  ui_story_5009_50090901_15_dialog_content = "¡Has hablado demasiado!",
  ui_story_5009_50090901_16_dialog_content = "Déjame la lucha a mí, PlayerName. Encuentras la salida.",
  ui_story_5009_50090901_17_dialog_content = "Oye, un minuto aquí. Aún no tienes idea de lo que está pasando, ¿verdad?",
  ui_story_5009_50090901_18_dialog_content = "Este es mi mundo.",
  ui_story_5009_50090901_19_dialog_content = "Por favor, recuerde que no es prudente oponerse a mí aquí.",
  ui_story_5009_50090901_20_dialog_content = "¡Tonterías!",
  ui_story_5009_50090901_21_dialog_content = "¡Esto es Eraveil y no te pertenece!",
  ui_story_5009_50090901_22_dialog_content = "¡No puedo tolerar tus acciones aquí!",
  ui_story_5009_50090901_23_dialog_content = "¿En serio? ¿Por qué no me muestras lo que tienes?",
  ui_story_5009_50090901_24_dialog_content = "Si hace un buen esfuerzo, consideraré concederle una muerte rápida.",
  ui_story_5009_50090901_25_dialog_content = "¡Nunca digas que no te di una oportunidad! ¿Qué te parece, Carleen? Ups, perdona mi rudeza.",
  ui_story_5009_50090901_26_dialog_content = "Sin embargo... Hmm.",
  ui_story_5009_50090901_27_dialog_content = "¿Debo dirigirme a usted como Su Alteza o Capitán?",
  ui_story_5009_50090901_28_dialog_content = "¡No eres apto para llamarla por ninguno de los dos títulos!",
  ui_story_5009_50090901_29_dialog_content = "Traidor de la Luz, violador de las leyes de Lumopolis... *Tose*",
  ui_story_5009_50090901_30_dialog_content = "¡Estás sufriendo, Pittman!",
  ui_story_5009_50090901_31_dialog_content = "Los traidores nunca terminan bien, Mirren Gautier.",
  ui_story_5009_50090901_32_dialog_content = "Mi lanza será tu veredicto.",
  ui_story_5009_50090901_33_dialog_content = "¡Vaya, te pido disculpas, Carleen, la personificación de la rectitud!",
  ui_story_5009_50090901_34_dialog_content = "Veo lo equivocado que estaba. ¿Debería arrodillarme y arrepentirme?",
  ui_story_5009_50090901_35_dialog_content = "No lo hice a propósito, de verdad... ¡Jajaja!",
  ui_story_5009_50090901_36_dialog_content = "¡Muere, Mirren Gautier!",
  ui_story_5009_50090901_37_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5009_50090901_38_dialog_content = "¿Por qué este nombre suena tan desagradable al salir de tu boca?",
  ui_story_5009_50090901_39_dialog_content = "Gautier es un apellido noble transmitido de generación en generación en Lumopolis, ¡indigno de pertenecer a alguien como tú!",
  ui_story_5009_50090901_40_dialog_content = "¿En serio? Sin embargo, los Gautier han estado bajo el control de ustedes, Schwartz ... No, que sea la gran Lumopolis.",
  ui_story_5009_50090901_41_dialog_content = "Mi familia, nuestro nombre, nuestra gloria ... Lo arruinaste sin ninguna razón hace mucho tiempo ...",
  ui_story_5009_50090901_42_dialog_content = "¡Tonterías!",
  ui_story_5009_50090901_43_dialog_content = "Lumopolis trató a los Gautiers y Pyrrhuses con guantes de cabrito después de la insurgencia.",
  ui_story_5009_50090901_44_dialog_content = "Hasta que finalmente se vieron obligados a adoptar medidas extremas.",
  ui_story_5009_50090901_45_dialog_content = "Te mereces lo que tienes.",
  ui_story_5009_50090901_46_dialog_content = "¿Es eso lo que lees en los libros de texto, querida princesa?",
  ui_story_5009_50090901_47_dialog_content = "No me sorprende, desde la historia de Lumopolis, como tú...",
  ui_story_5009_50090901_48_dialog_content = "Es fácilmente maleable por otros.",
  ui_story_5009_50090901_49_dialog_content = "No desperdiciemos el aliento con esta escoria, alteza.",
  ui_story_5009_50090901_50_dialog_content = "Más precisamente, este es el cerebro de la insurrección y un delincuente buscado.",
  ui_story_5009_50090901_51_dialog_content = "¡Ven ahora, señoría! ¿Crees que estás en tu tribunal de justicia más santo que tú?",
  ui_story_5009_50090901_52_dialog_content = "¿Le gustaría que me arrodillara y expiara también?",
  ui_story_5009_50090901_53_dialog_content = "¡Hablas demasiado, Mirren!",
  ui_story_5009_50090901_54_dialog_content = "Este delincuente probablemente lo mantuvo reprimido durante demasiado tiempo y solo estaba esperando una oportunidad para desahogarse.",
  ui_story_5009_50090901_55_dialog_content = "Suena como un villano que ha sido agraviado. ¿Pero dónde lo he visto antes...?",
  ui_story_5009_50090901_56_dialog_content = "¿Desahogarse? ¿Explotado? No, no, no.",
  ui_story_5009_50090901_57_dialog_content = "Aunque los Gautiers agraviados y asesinados por Lumopolis deberían poder desahogarse contigo lo suficientemente pronto.",
  ui_story_5009_50090901_58_dialog_content = "Excepto por nuestra noble Carleen, el resto de ustedes tiene que morir.",
  ui_story_5009_50090901_59_dialog_content = "¡Traidor desvergonzado! ¡Comenzaste la rebelión! ¡Eres el verdadero asesino!",
  ui_story_5009_50090901_60_dialog_content = "¿Es esa la conclusión o el veredicto, señoría?",
  ui_story_5009_50090901_61_dialog_content = "Je, el juicio no tiene sentido sin el verdadero poder.",
  ui_story_5009_50090901_62_dialog_content = "Puede pedirle a mi gente la verdad una vez que esté muerto.",
  ui_story_5009_50090901_63_dialog_content = "Ahora, te daré...",
  ui_story_5009_50090901_64_option_content = "¡Explosión entrante!",
  ui_story_5009_50090901_65_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5009_50090901_66_dialog_content = "Que demonios...?",
  ui_story_5009_50090901_67_dialog_content = "¡Rómpelo!",
  ui_story_5009_50090901_68_dialog_content = "¡Argh!",
  ui_story_5009_50090901_69_dialog_content = "¿Están todos bien?",
  ui_story_5009_50090901_70_dialog_content = "Estoy aquí, PlayerName. Todos están bien.",
  ui_story_5009_50090901_71_dialog_content = "¡Estaban fuera!",
  ui_story_5009_50090901_72_dialog_content = "Su Luminatics es realmente asombroso, Capitán Carleen.",
  ui_story_5009_50090901_73_dialog_content = "No fui yo.",
  ui_story_5009_50090901_74_dialog_content = "Mantente alerta, todavía estamos bajo el eclipse.",
  ui_story_5009_50090901_75_dialog_content = "Qué fue eso, PlayerName?",
  ui_story_5009_50090901_76_dialog_content = "Sentí al Aurorian que estaba en el cementerio.",
  ui_story_5009_50090901_77_dialog_content = "Entonces, el Aurorian en la batalla de ahora ...",
  ui_story_5009_50090901_78_dialog_content = "¡Derecha! ¡Ese enorme estallido repentino de energía justo ahora debe haber sido del mismo Aurorian!",
  ui_story_5009_50090901_79_dialog_content = "Penetró la barrera dimensional y golpeó a Mirren.",
  ui_story_5009_50090901_80_dialog_content = "Nunca había visto una ofensa como esa. ¡Ese Aurorian tiene un ocultamiento aterrador y poderes destructivos!",
  ui_story_5009_50090901_81_dialog_content = "¿Tampoco has visto nunca Luminatics como ese?",
  ui_story_5009_50090901_82_dialog_content = "¡Eh, no puedo creer que haya recibido un cumplido de su alteza Carleen!",
  ui_story_5009_50090901_83_dialog_content = "¿Quién eres?",
  ui_story_5009_50090901_84_dialog_content = "* Tos * ... Supuse que eras tú.",
  ui_story_5009_50090901_85_dialog_content = "Permítanme presentarles. Esta señora es de Lumopolis ...",
  ui_story_5009_50090901_86_dialog_content = "No, espera, haz eso del True Order, Paloma Py ...",
  ui_story_5009_50090901_87_dialog_content = "Paloma Pyrrhus? ¿De la casa de Pyrrhus?",
  ui_story_5009_50090901_88_dialog_content = "¡Seguro que es astuto y observador, señoría!",
  ui_story_5009_50090901_89_dialog_content = "¿No está emocionado de ver a dos delincuentes buscados de dos casas rebeldes el mismo día?",
  ui_story_5009_50090901_90_dialog_content = "¿Eres Paloma Pyrrhus? ¿Cómo puedes ser un Pyrrhus? Pensé que Caroline...",
  ui_story_5009_50090901_91_dialog_content = "Llámame Paloma, alteza.",
  ui_story_5009_50090901_92_dialog_content = "¡Eres tú, Paloma! Has cambiado mucho.",
  ui_story_5009_50090901_93_dialog_content = "Bien, me estoy confundiendo mucho ahora...",
  ui_story_5009_50090901_94_dialog_content = "House of Pyrrhus y House of Gautier son co-conspiradores, PlayerName, lo que hace que Paloma aquí...",
  ui_story_5009_50090901_95_dialog_content = "No olvidemos, señoría ...",
  ui_story_5009_50090901_96_dialog_content = "Paloma aquí no es solo un miembro de la insurgente Casa de Pyrrhus, sino una ex monja que le dio la espalda a la Luz.",
  ui_story_5009_50090901_97_dialog_content = "Si estoy en lo cierto, ella también está en tu supuesta lista negra de buscados, ¿verdad? ¿No deberían estar deteniéndola, guerreros justos?",
  ui_story_5009_50090901_98_dialog_content = "La forma en que Lumopolis hace cumplir su ley no es asunto suyo.",
  ui_story_5009_50090901_99_dialog_content = "Es tan aburrido escuchar a todos ustedes discutir.",
  ui_story_5009_50090901_100_dialog_content = "Mirren Gautier debe morir. Cualquier otra cosa, no me importa.",
  ui_story_5009_50090901_101_dialog_content = "¡Sabía que Mirren había comenzado todo esto!",
  ui_story_5009_50090901_102_dialog_content = "Pero, ¿cómo se involucró la Casa de Pyrrhus?",
  ui_story_5009_50090901_103_dialog_content = "Puede continuar con su consulta como desee, señoría.",
  ui_story_5009_50090901_104_dialog_content = "Pero estoy aquí para vengarme, no para construir un caso.",
  ui_story_5009_50090901_105_dialog_content = "Oh, es tan conmovedor cuando los viejos amigos se reencuentran.",
  ui_story_5009_50090901_106_dialog_content = "¡Cuántas veces tengo que decirte, Paloma, que los poderes fácticos de Lumopolis son los que mataron a tu gente!",
  ui_story_5009_50090901_107_dialog_content = "¡La arrogante y engreída Carleen Schwartz debería ser la que buscas aquí!",
  ui_story_5009_50090901_108_dialog_content = "Por supuesto, el honorable juez también.",
  ui_story_5009_50090901_109_dialog_content = "Parece que tenemos una comprensión diferente de la mente maestra.",
  ui_story_5009_50090901_110_dialog_content = "Pero entonces, no se puede esperar que un Eclipsite comprenda por completo el idioma Aurorian.",
  ui_story_5009_50090901_111_dialog_content = "¡No vayas en mi contra!",
  ui_story_5009_50090901_112_dialog_content = "Esta es tu última oportunidad.",
  ui_story_5009_50090901_113_dialog_content = "Venganza exacta contra Lumopolis conmigo, o morir junto a ellos. Elige una.",
  ui_story_5009_50090901_114_dialog_content = "Veo que solo la muerte puede curarte y frenar tu verbosidad.",
  ui_story_5009_50090901_115_dialog_content = "¿Curar? Eso realmente me iluminó al hecho de que no tengo que matarte ...",
  ui_story_5009_50090901_116_dialog_content = "El gran maestro estaría encantado de que le entregara un juguete nuevo.",
  ui_story_5009_50090901_117_dialog_content = "Una poderosa y hermosa mujer Aurorian.",
  ui_story_5009_50090901_118_dialog_content = "Mmm. Me gustaría verte intentarlo.",
  ui_story_5009_50090901_119_dialog_content = "¿Qué está pasando acá? ¿Paloma nos está ayudando a luchar?",
  ui_story_5009_50090901_120_dialog_content = "Ella es poderosa. Puede que Mirren no gane.",
  ui_story_5009_50090901_121_dialog_content = "Paloma ocupa un lugar destacado en la lista más peligrosa de la iglesia. Ella le dio la espalda por completo a la Luz para unirse a True Order.",
  ui_story_5009_50090901_122_dialog_content = "El True Order... Parece que Paloma ha aprendido Luminatics especiales de ellos.",
  ui_story_5009_50090901_123_dialog_content = "Luminoso que no se vio afectado por el eclipse y fue lo suficientemente poderoso como para romper la barrera dimensional.",
  ui_story_5009_50090901_124_dialog_content = "Espera, creo que la conversación entre Paloma y ese Eclipsite se trata de ...",
  ui_story_5009_50090901_125_dialog_content = "Oye, ¿vas a dejar de hablar o qué?",
  ui_story_5009_50090901_126_dialog_content = "Mirren tiene refuerzos y no estoy aquí para protegerte.",
  ui_story_5009_50090901_127_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_5009_50090901_128_dialog_content = "Esto es malo, siento que los Eclipsites se acercan a nosotros...",
  ui_story_5009_50090901_129_dialog_content = "Está bien, ¡nuestros respaldos también están aquí!",
  ui_story_5009_50090901_130_dialog_content = "¿Todavía puedes coordinar, PlayerName?",
  ui_story_5009_50090901_131_dialog_content = "¡Lo tengo!",
  ui_story_5009_50090902_1_dialog_content = "¿Realmente vamos a pelear, Señorita Pyrrhus?",
  ui_story_5009_50090902_2_dialog_content = "¿Repitiendo las mismas líneas, Sr. Gautier?",
  ui_story_5009_50090902_3_dialog_content = "Esto es diferente, ya que dos traidores de Lumopolis luchan ante sus poderes fácticos.",
  ui_story_5009_50090902_4_dialog_content = "¿Quién crees que se beneficiará más?",
  ui_story_5009_50090902_5_dialog_content = "Tengo mucho tiempo para pensar en eso una vez que estés muerto.",
  ui_story_5009_50090902_6_dialog_content = "Nos ablandamos mutuamente para que ellos hagan cumplir la llamada justicia al final. Excelente.",
  ui_story_5009_50090902_7_dialog_content = "¡Si moríamos, ese sería realmente el fin del linaje de Gautiers y Pyrrhuses!",
  ui_story_5009_50090902_8_dialog_content = "Ambos probamos la justicia de Lumopolis, Paloma.",
  ui_story_5009_50090902_9_dialog_content = "Las hazañas de Pyrrhuses han traído vergüenza a Lumopolis, por favor perdónanos, Dios de la Luz.",
  ui_story_5009_50090902_10_dialog_content = "Estamos dispuestos a aceptar el castigo a cambio de tu misericordia.",
  ui_story_5009_50090902_11_dialog_content = "El dolor de perder los poderes de Lumina siempre servirá como un recordatorio para no cometer el mal ...",
  ui_story_5009_50090902_12_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5009_50090902_13_dialog_content = "Asentamiento del Exilio 14, ¿hay alguien? Soy un mensajero de Lumopolis.",
  ui_story_5009_50090902_14_dialog_content = "Abre la puerta y firma, Paloma.",
  ui_story_5009_50090902_15_dialog_content = "Seguro, padre.",
  ui_story_5009_50090902_16_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5009_50090902_17_dialog_content = "La vida en la Baja Lumopolis ha sido difícil durante el último año. Todos hemos sufrido ...",
  ui_story_5009_50090902_18_dialog_content = "Claramente fue su culpa, entonces, ¿por qué tenemos que sufrir nosotros también?",
  ui_story_5009_50090902_19_dialog_content = "No me importa si solo somos nosotros dos, pero nuestro hijo...",
  ui_story_5009_50090902_20_dialog_content = "¿Y qué? El peor escenario es que abandonemos la iglesia, perdamos los poderes de Lumina y vivamos como plebeyos.",
  ui_story_5009_50090902_21_dialog_content = "Pero secuestrar a los niños de Gautier para transformarlos es un pecado mayor, no un delito menor.",
  ui_story_5009_50090902_22_dialog_content = "Pero... Pero, ¿qué tiene eso que ver con nosotros?",
  ui_story_5009_50090902_23_dialog_content = "Los Schwartz nunca se preocuparon por otros nobles.",
  ui_story_5009_50090902_24_dialog_content = "¡Cállate, tú!",
  ui_story_5009_50090902_25_dialog_content = "¿Sabes que incluso los inocentes Gautiers han sido desterrados a la Baja Lumopolis?",
  ui_story_5009_50090902_26_dialog_content = "¿¡Q-Q-de qué estás hablando !?",
  ui_story_5009_50090902_27_dialog_content = "Solo resígnate al destino. Alégrate de que todavía estamos vivos.",
  ui_story_5009_50090902_28_dialog_content = "...",
  ui_story_5009_50090902_29_dialog_content = "Padre, madre, ¿conocen a Mirren Gautier?",
  ui_story_5009_50090902_30_dialog_content = "¿Mirren?",
  ui_story_5009_50090902_31_dialog_content = "¿No es ese el pintor de renombre de la Casa Gautier?",
  ui_story_5009_50090902_32_dialog_content = "¿Por qué preguntas, Paloma?",
  ui_story_5009_50090902_33_dialog_content = "Este es un aviso que acabamos de recibir del Salón de Justicia. Dice que Mirren Gautier es un elemento peligroso.",
  ui_story_5009_50090902_34_dialog_content = "Si ve a esta persona, repórtelo a las autoridades de inmediato.",
  ui_story_5009_50090902_35_dialog_content = "¿En serio? Tu tío me habló de él hace unos días.",
  ui_story_5009_50090902_36_dialog_content = "Mi hermano también mencionó este nombre cuando charlamos ayer.",
  ui_story_5009_50090902_37_dialog_content = "Tengo un mal presentimiento sobre esto. Todos deberíamos andar con cuidado.",
  ui_story_5009_50090902_38_dialog_content = "Entendido, fa...",
  ui_story_5009_50090902_39_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5009_50090902_40_dialog_content = "Vamos, vamos...",
  ui_story_5009_50090902_41_dialog_content = "¡Corre, el ejército de Lumopolis ha rodeado el asentamiento!",
  ui_story_5009_50090902_42_dialog_content = "¿Qué?",
  ui_story_5009_50090902_43_dialog_content = "Más despacio, tómatelo con calma.",
  ui_story_5009_50090902_44_dialog_content = "Mirren Gautier está usurpando. ¡Tanto el ejército como la iglesia están en marcha!",
  ui_story_5009_50090902_45_dialog_content = "¿La casa de Gautier? ¿Levantamiento?",
  ui_story_5009_50090902_46_dialog_content = "¿La Iglesia? ¿Por qué reaccionaría la iglesia?",
  ui_story_5009_50090902_47_dialog_content = "Mirren supuestamente utilizó la transformación, y los Pyrrhuses y Eclipsites han estado implicados en la insurrección.",
  ui_story_5009_50090902_48_dialog_content = "Debo irme. Tú también deberías correr.",
  ui_story_5009_50090902_49_dialog_content = "¡Y esto tiene algo que ver con nosotros, de nuevo!",
  ui_story_5009_50090902_50_dialog_content = "Si conozco Lumopolis como lo hago, esta será una persecución a gran escala.",
  ui_story_5009_50090902_51_dialog_content = "Como Pyrrhus, no debemos preocuparnos siempre que seamos juzgados con justicia.",
  ui_story_5009_50090902_52_dialog_content = "Eres demasiado idealista, hijo mío...",
  ui_story_5009_50090902_53_dialog_content = "Escúchame y escóndete. Lo comprobaré con tu madre.",
  ui_story_5009_50090902_54_dialog_content = "Ven conmigo ahora, Paloma. Nadie se irá si esperamos más.",
  ui_story_5009_50090902_55_dialog_content = "¡Ve!",
  ui_story_5009_50090902_56_dialog_content = "¡Por decreto del señor, maten a los traidores! ¡Por decreto del señor, maten a los traidores!",
  ui_story_5009_50090902_57_dialog_content = "¿Por qué están peleando? ¿Y de dónde vienen los monstruos?",
  ui_story_5009_50090902_58_dialog_content = "¡¿Eh?! ¡Ésta es toda nuestra gente! Eclipsites... ¡Se han transformado en Eclipsites!",
  ui_story_5009_50090902_59_dialog_content = "Se acabó... Este es el final de los Pyrrhuses.",
  ui_story_5009_50090902_60_dialog_content = "¡Castiga a los rebeldes! ¡Castiga a los rebeldes! ¡Castiga a los rebeldes!",
  ui_story_5009_50090902_62_dialog_content = "La justicia de Lumopolis... ¡Ja! Tengo mucha experiencia con eso.",
  ui_story_5009_50090902_63_dialog_content = "* Tos * Entonces ... cancela tu ataque ...",
  ui_story_5009_50090902_64_dialog_content = "Todo se remonta a Lumopolis...",
  ui_story_5009_50090902_65_dialog_content = "Muy bien, Mirren Gautier. Una vez que estés muerta, me aseguraré de enviar al alcalde para que te haga compañía.",
  ui_story_5009_50090902_66_dialog_content = "Pero lo primero es lo primero... Es hora de morir.",
  ui_story_5009_50090902_67_dialog_content = "Señorita Paloma Pyrrhus ... Si así es como termina, todo lo que puedo hacer es enterrarte como es debido, con esos guerreros justos.",
  ui_story_5009_50090902_68_dialog_content = "Tus palabras son tan hiperbólicas como siempre ...",
  ui_story_5009_50091001_1_dialog_content = "Rayos... Mis habilidades psíquicas aún no se han recuperado por completo...",
  ui_story_5009_50091001_2_dialog_content = "Está bien, PlayerName! ¡Tus órdenes todavía eran precisas en este momento!",
  ui_story_5009_50091001_3_dialog_content = "¿Y el monstruo? ¿A dónde fue?",
  ui_story_5009_50091001_4_dialog_content = "¡Todavía está cerca! Pero su poder parece estar ... ¿creciendo?",
  ui_story_5009_50091001_5_dialog_content = "¡Pero el ataque anterior de Paloma lo hirió gravemente! ¡Todos lo vimos! A menos que...",
  ui_story_5009_50091001_6_dialog_content = "Parece estar devorando a los Eclipsites cercanos para recuperar su Darkflow.",
  ui_story_5009_50091001_7_dialog_content = "Ugh... ¡No de nuevo! ¡Es asqueroso!",
  ui_story_5009_50091001_8_dialog_content = "¿Escuchaste eso, Paloma?",
  ui_story_5009_50091001_9_dialog_content = "¡Ese monstruo todavía está al acecho en algún lugar cercano! ¡Mantente en guardia!",
  ui_story_5009_50091001_10_dialog_content = "Solo preocúpense por ustedes mismos y manténganse fuera de mi camino.",
  ui_story_5009_50091001_11_dialog_content = "¡¡Una ola de Darkflow!!",
  ui_story_5009_50091001_12_dialog_content = "¡Oh no, viene de la dirección de Paloma! ¡El monstruo está haciendo su ataque!",
  ui_story_5009_50091001_13_dialog_content = "Esto es malo...",
  ui_story_5009_50091001_14_option_content = "¡Potencia de fuerza!",
  ui_story_5009_50091001_15_dialog_content = "Paloma! ¡Esquiva hacia tu frente a la izquierda!",
  ui_story_5009_50091001_16_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5009_50091001_17_dialog_content = "Estás... ¿Estás bien, Paloma?",
  ui_story_5009_50091001_18_dialog_content = "* tos, tos * ¿Es esto ... el poder de los celestitas?",
  ui_story_5009_50091001_19_dialog_content = "Transmitiendo pensamientos a mi mente al instante ...",
  ui_story_5009_50091001_20_dialog_content = "¿No deberías pedir permiso primero?",
  ui_story_5009_50091001_21_dialog_content = "si no fuera por PlayerName forzó el poder para ayudarte a esquivar...",
  ui_story_5009_50091001_22_dialog_content = "La emboscada de Mirren habría tenido éxito.",
  ui_story_5009_50091001_23_dialog_content = "Mirren ... se escabulle y ataca como una rata.",
  ui_story_5009_50091001_24_dialog_content = "¡Ja! ¡Me gusta esa actitud suya, pequeña señorita Illumina!",
  ui_story_5009_50091001_25_dialog_content = "Estoy bien, ¡así que no te preocupes por mí!",
  ui_story_5009_50091001_26_dialog_content = "¡Tenemos que hacer todo lo posible para encontrarlo, antes de que escape!",
  ui_story_5009_50091001_27_dialog_content = "Si no puedes atacar, huye. Estilo típico de Mirren Gautier.",
  ui_story_5009_50091001_28_dialog_content = "Pareces conocerlo bien, Paloma.",
  ui_story_5009_50091001_29_dialog_content = "Hmph... Todo lo que sé de él es su enfoque cobarde para el combate.",
  ui_story_5009_50091002_1_dialog_content = "¡Las familias Gautier y Pyrrhus, se rebelaron contra la autoridad y conspiraron con los Eclipsites! ¡Nunca olvides su traición!",
  ui_story_5009_50091002_2_dialog_content = "¡Castiga a los rebeldes! ¡Mata a los Eclipsites!",
  ui_story_5009_50091002_3_dialog_content = "¡Todos, por favor! ¡No somos más que parientes de la familia Pyrrhus! ¡Por favor entiende!",
  ui_story_5009_50091002_4_dialog_content = "La suya es una familia de traidores rebeldes, que se atrevieron a conspirar con los Eclipsites y usar sus técnicas, ¡nada menos! ¡No mereces piedad!",
  ui_story_5009_50091002_5_dialog_content = "Si esto tiene que ver con los experimentos con cristales... ¡Ya hemos sido castigados por eso, oficial!",
  ui_story_5009_50091002_6_dialog_content = "Nos privaron de nuestra Lumina y nos arrojaron a la Baja Lumopolis ...",
  ui_story_5009_50091002_7_dialog_content = "Rezamos al Dios de la Luz todos los días, suplicando perdón... ¡Te aseguro que esta es la verdad!",
  ui_story_5009_50091002_8_dialog_content = "Esos Eclipsites transformados hace un momento... ¡Eran miembros de la familia Pyrrhus!",
  ui_story_5009_50091002_9_dialog_content = "Nosotros ... no somos como ellos ...",
  ui_story_5009_50091002_10_dialog_content = "¡No nos hemos transformado!",
  ui_story_5009_50091002_A1_dialog_content = "¡Eres culpable, todos y cada uno de ustedes! ¡Guardias! ¡Consíguelos!",
  ui_story_5009_50091002_11_dialog_content = "¡Padre! ¡Madre! ¿Qué está pasando acá?",
  ui_story_5009_50091002_12_dialog_content = "Paloma ...?! ¡Corre, Paloma! ¡¡Huye!!",
  ui_story_5009_50091002_13_dialog_content = "Padre... ¡Madre..!",
  ui_story_5009_50091002_14_dialog_content = "¿Paloma? ¡Ven conmigo, date prisa!",
  ui_story_5009_50091002_15_dialog_content = "Urgh...",
  ui_story_5009_50091002_16_dialog_content = "¡Mantente alejado de ella!",
  ui_story_5009_50091002_17_dialog_content = "¿Estás loca, mujer? ¡Cómo te atreves a morderme!",
  ui_story_5009_50091002_18_dialog_content = "¡Que mucho! ¡Ve tras la chica!",
  ui_story_5009_50091002_19_dialog_content = "¡Sí señor!",
  ui_story_5009_50091002_20_dialog_content = "Paloma, por favor ... Tienes que comer algo.",
  ui_story_5009_50091002_21_dialog_content = "¿Por qué...? ¿Para qué son todos estos ...?",
  ui_story_5009_50091002_22_dialog_content = "Padre... Madre... ¿Estarán bien...?",
  ui_story_5009_50091002_23_dialog_content = "Han pasado tres días, Paloma. Necesita darse tiempo para descansar.",
  ui_story_5009_50091002_24_dialog_content = "Ah... Tu... Estás de vuelta... ¿Has aprendido algo sobre mis padres?",
  ui_story_5009_50091002_25_dialog_content = "Yo... Solo he escuchado malas noticias. Si desea escucharlo, deberá prepararse mentalmente.",
  ui_story_5009_50091002_26_dialog_content = "Nuestros parientes han sido prácticamente masacrados por las fuerzas de Lumopolis, junto con ...",
  ui_story_5009_50091002_27_dialog_content = "......",
  ui_story_5009_50091002_28_dialog_content = "Seguramente, entiendes lo que estoy tratando de decirte ... ¿verdad?",
  ui_story_5009_50091002_29_dialog_content = "No tengo idea de dónde aprendió Mirren Gautier esas técnicas, pero secuestró a varios de nuestros parientes y experimentó con ellos.",
  ui_story_5009_50091002_30_dialog_content = "Poco después, la familia Gautier inició su rebelión.",
  ui_story_5009_50091002_31_dialog_content = "Transformaron ... ¿a los miembros de nuestra familia? ¿Se estaban vengando de la familia Pyrrhus?",
  ui_story_5009_50091002_32_dialog_content = "No completamente. Se creen las víctimas y que todas fueron exiliadas como iguales por las autoridades.",
  ui_story_5009_50091002_33_dialog_content = "Me imagino que su animosidad hacia la nobleza de Lumopolis jugó un papel importante en su rebelión.",
  ui_story_5009_50091002_34_dialog_content = "En cualquier caso, esta masacre fue un caso más del castigo indiscriminado de Lumopolis. Para los nobles, esta es la respuesta más completa a sus problemas.",
  ui_story_5009_50091002_35_dialog_content = "¿Entonces no hay verdad real o justicia en eso...?",
  ui_story_5009_50091002_36_dialog_content = "La verdad es ... demasiado complicada y empañaría la reputación de la nobleza.",
  ui_story_5009_50091002_37_dialog_content = "¿En cuanto a la justicia? Bueno ... toda nuestra familia ha sido aniquilada. En lo que respecta a los forasteros, esto es justicia.",
  ui_story_5009_50091002_38_dialog_content = "Entonces, ¿y nosotros? ¡Somos inocentes!",
  ui_story_5009_50091002_39_dialog_content = "Las fuerzas del destino consideraron oportuno dejarnos sobrevivir. Pensar demasiado en ello no nos servirá de nada.",
  ui_story_5009_50091002_40_dialog_content = "No... Esto está mal. No puede ser... Esto no es justicia, en absoluto.",
  ui_story_5009_50091002_41_dialog_content = "La parte más irónica es que a pesar de que las familias Gautier y Pyrrhus han sido exterminadas, Mirren todavía está ahí fuera, no pueden llegar a él.",
  ui_story_5009_50091002_42_dialog_content = "Mirren Gautier... No es mucho mayor que tú ahora.",
  ui_story_5009_50091002_43_dialog_content = "Era solo un niño al que le encantaba dibujar... No puedo entender cómo obtiene tal conocimiento.",
  ui_story_5009_50091002_44_dialog_content = "¿Todavía no está muerto? Bien... Sé lo que tengo que hacer ahora.",
  ui_story_5009_50091002_45_dialog_content = "Bueno, piensa en tus padres. Estoy seguro de que ambos te desean una vida feliz.",
  ui_story_5009_50091002_46_dialog_content = "Madre... Padre...",
  ui_story_5009_50091002_47_dialog_content = "¿Has olvidado? Ni siquiera puedes vencer al más joven de los guardias ahora.",
  ui_story_5009_50091002_48_dialog_content = "Quieres decir, sin Luminatics, ni siquiera puedo ...",
  ui_story_5009_50091002_49_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5009_50091002_50_dialog_content = "¡Castiga a los rebeldes! ¡Mata a los Eclipsites!",
  ui_story_5009_50091002_51_dialog_content = "¡Este lugar alberga a fugitivos de la familia Pyrrhus! ¡Cázalos!",
  ui_story_5009_50091002_52_dialog_content = "¡Corre, Paloma!",
  ui_story_5009_50091002_53_dialog_content = "¡No sin ti!",
  ui_story_5009_50091002_54_dialog_content = "¡Tienes que seguir viviendo, Paloma! Para vengarnos... ¡Tienes que sobrevivir!",
  ui_story_5009_50091101_1_dialog_content = "¡No bajen la guardia, todos! ¡Manténgase alerta!",
  ui_story_5009_50091101_2_dialog_content = "Pero no siento más Eclipsites cerca...",
  ui_story_5009_50091101_3_dialog_content = "Está bien. Solo les recuerda a todos que tengan cuidado conmigo.",
  ui_story_5009_50091101_4_dialog_content = "Después de todo, soy un fugitivo de la traidora familia Pyrrhus y un miembro del blasfemo True Order. Según todas las cuentas, soy muy peligroso y no se puede confiar en él.",
  ui_story_5009_50091101_5_dialog_content = "Si tuvieras alguna mala intención hacia nosotros, podrías habernos matado a todos con tus poderes destructivos antes de que lo supiéramos.",
  ui_story_5009_50091101_6_dialog_content = "...Está bien, es suficiente. ¡Vamos a buscar a Mirren!",
  ui_story_5009_50091101_7_dialog_content = "El Eclipse aún no se ha disipado, por lo que aún debería estar cerca.",
  ui_story_5009_50091101_8_dialog_content = "Intentaré sentirlo de nuevo.",
  ui_story_5009_50091101_9_dialog_content = "No tienes que esforzarte demasiado, PlayerName.",
  ui_story_5009_50091101_10_dialog_content = "Estaré bien, Vice. Está bajo mi control.",
  ui_story_5009_50091101_11_dialog_content = "Si puedes encontrarlo, tengo una forma de acabar con él.",
  ui_story_5009_50091101_12_option_content = "Sensación",
  ui_story_5009_50091101_13_dialog_content = "Paloma! ¡Corre!",
  ui_story_5009_50091101_A2_dialog_content = "¡Corre!",
  ui_story_5009_50091101_14_dialog_content = "Padre... ¡Madre..!",
  ui_story_5009_50091101_A1_dialog_content = "¿Paloma? ¡Ven conmigo! ¡Apúrate!",
  ui_story_5009_50091101_15_dialog_content = "Urgh...",
  ui_story_5009_50091101_16_dialog_content = "¡Mantente alejado de ella!",
  ui_story_5009_50091101_17_dialog_content = "¿Estás loca, mujer? ¡Cómo te atreves a morderme!",
  ui_story_5009_50091101_18_dialog_content = "P... ¿Paloma?",
  ui_story_5009_50091101_19_dialog_content = "¿Ah? ¿Por qué me miras?",
  ui_story_5009_50091101_20_dialog_content = "Oh... Creo que tus fuertes emociones están interfiriendo con mis habilidades psíquicas.",
  ui_story_5009_50091101_21_dialog_content = "Hmph.",
  ui_story_5009_50091101_22_dialog_content = "Me quedaré más lejos para que mis \"emociones fuertes\" no se interpongan en el camino.",
  ui_story_5009_50091101_23_dialog_content = "¿Emociones fuertes...? Parece que el odio de Paloma por Mirren debe ser bastante fuerte.",
  ui_story_5009_50091101_24_dialog_content = "Aunque Paloma habla poco, creo que finalmente lo he descubierto.",
  ui_story_5009_50091101_25_dialog_content = "Si Mirren es de hecho la mente maestra detrás de todos los conflictos, entonces tiene perfecto sentido.",
  ui_story_5009_50091101_26_dialog_content = "¿Oh?",
  ui_story_5009_50091101_27_dialog_content = "Srta. Carleen, la familia Pyrrhus fue la responsable de provocar el incidente con Beryl.",
  ui_story_5009_50091101_28_dialog_content = "Por esta razón, la familia Gautier creyó que fueron injustamente exiliados como consecuencia de las acciones de la familia Pyrrhus.",
  ui_story_5009_50091101_29_dialog_content = "Para vengarse, Mirren orquestó la rebelión de la familia Gautier.",
  ui_story_5009_50091101_30_dialog_content = "Para Paloma y sus parientes, que ambas familias sean masacradas como resultado del complot de Mirren también es injusto.",
  ui_story_5009_50091101_31_dialog_content = "Como tal, la disputa entre las dos familias no es nada simple.",
  ui_story_5009_50091101_32_dialog_content = "Y Paloma nunca podría perdonar a Mirren, quien fue la causa directa de la muerte de su familia.",
  ui_story_5009_50091101_33_dialog_content = "Espera un minuto... ¿No es todo causado por la falta de juicio justo de la autoridad de Lumopolis?",
  ui_story_5009_50091101_34_dialog_content = "...",
  ui_story_5009_50091101_35_dialog_content = "Aún quedan muchos detalles por aclarar. Tenga la seguridad, Srta. Carleen. Continuaré investigando el asunto lo mejor que pueda.",
  ui_story_5009_50091101_36_dialog_content = "Una cosa que todavía no entiendo es por qué tanto Mirren como Paloma poseen un poder tan increíble.",
  ui_story_5009_50091101_37_dialog_content = "Estoy parado justo aquí, ¿sabes?",
  ui_story_5009_50091101_38_dialog_content = "¿Es realmente tan extraño para mí ser tan poderoso, considerando que he caído tan bajo como para haberme unido a la True Order?",
  ui_story_5009_50091101_39_dialog_content = "En cuanto a Mirren, por lo que he recopilado, su poder tiene algo que ver con esa misteriosa organización...",
  ui_story_5009_50091101_40_dialog_content = "Mis pensamientos precisamente, señorita Paloma.",
  ui_story_5009_50091101_41_dialog_content = "Incluso los eventos de hace diecisiete años, y todo lo que ha llevado hasta hoy, podría atribuirse a...",
  ui_story_5009_50091101_42_dialog_content = "No andes con rodeos palabras así. Ustedes dos están hablando de Eclipse, ¿verdad?",
  ui_story_5009_50091101_43_dialog_content = "Hemos peleado con ellos antes. Se podría decir que ahora somos viejos conocidos, ¿verdad? PlayerName?",
  ui_story_5009_50091101_44_dialog_content = "Espera...",
  ui_story_5009_50091101_45_dialog_content = "¡Puedo sentir algo! ¡Mirren todavía no se ha escapado de Eraveil!",
  ui_story_5009_50091101_46_dialog_content = "Hay una cueva subterránea ... ¡Muchos Eclipsites de alto nivel están inactivos allí!",
  ui_story_5009_50091101_47_dialog_content = "¿Qué planea hacer allí?",
  ui_story_5009_50091101_48_dialog_content = "¿No es obvio? Come las Eclipsites y recupera Darkflow.",
  ui_story_5009_50091101_49_dialog_content = "No podemos dejar que eso suceda ...",
  ui_story_5009_50091101_50_dialog_content = "PlayerName! ¡Dame una dirección!",
  ui_story_5009_50091101_51_dialog_content = "En algún lugar de allí.",
  ui_story_5009_50091101_52_dialog_content = "Puedes seguir usando habilidades psíquicas tan poderosas en Eclipse ... Estoy impresionado.",
  ui_story_5009_50091101_53_dialog_content = "Mirren Gautier... Voy por ti.",
  ui_story_5009_50091101_54_dialog_content = "¿Quieres ir sola, Paloma?",
  ui_story_5009_50091101_55_dialog_content = "¿Por qué no descansar un poco primero? ¡Podemos derrotarlo juntos una vez que todos recuperemos nuestras fuerzas!",
  ui_story_5009_50091101_56_dialog_content = "¿Oh? Entonces, te acabo de elogiar, ¿y ahora crees que puedes mandarme?",
  ui_story_5009_50091101_57_dialog_content = "¡Espera, Paloma!",
  ui_story_5009_50091101_58_dialog_content = "Ella despegó, así como así...",
  ui_story_5009_50091101_59_dialog_content = "Con sus poderes, está más que calificada para operar por su cuenta.",
  ui_story_5009_50091101_60_dialog_content = "Aun así, ella gastó gran parte de su fuerza en este momento. Si Mirren pudo recuperar su Darkflow...",
  ui_story_5009_50091101_61_dialog_content = "No creo que tenga posibilidades de ganar.",
  ui_story_5009_50091101_62_dialog_content = "Tenemos que darnos prisa y alcanzarla.",
  ui_story_5009_50091101_63_dialog_content = "Otro obstáculo en el camino, eh...",
  ui_story_5009_50091101_64_dialog_content = "¡Hagámoslo!",
  ui_story_5009_50091202_1_dialog_content = "¿Estás diciendo que conociste a Paloma, hace mucho tiempo?",
  ui_story_5009_50091202_2_dialog_content = "Sí... En ese entonces, ella era una niña tranquila, tímida e indefensa.",
  ui_story_5009_50091202_3_dialog_content = "Tranquilo, tímido ... ¿e indefenso?",
  ui_story_5009_50091202_4_dialog_content = "¿Seguimos hablando de la misma Paloma aquí?",
  ui_story_5009_50091202_5_dialog_content = "Nos conocimos en la Academia Dawn, hace muchos años.",
  ui_story_5009_50091202_6_dialog_content = "En ese momento, estaba convencida de que se convertiría en la monja más maravillosa, pero luego ...",
  ui_story_5009_50091202_7_dialog_content = "Vi su nombre escrito en la lista de fugitivos.",
  ui_story_5009_50091202_8_dialog_content = "Por los delitos de rebelarse en familia, además de traicionar a la iglesia...",
  ui_story_5009_50091202_9_dialog_content = "La familia Pyrrhus, junto con la familia Gautier, protagonizaron una violenta rebelión ...",
  ui_story_5009_50091202_10_dialog_content = "Si no hubiera escapado, ¿Paloma habría sido ejecutada por Lumopolis?",
  ui_story_5009_50091202_11_dialog_content = "¿Como el resto de su familia...?",
  ui_story_5009_50091202_12_dialog_content = "......",
  ui_story_5009_50091202_13_dialog_content = "Me siento como si... Puedo entenderla ahora.",
  ui_story_5009_50091202_14_dialog_content = "Siendo la última superviviente de su pueblo, y buscando una explicación para todos ...",
  ui_story_5009_50091202_15_dialog_content = "Entiendo completamente ese sentimiento.",
  ui_story_5009_50091202_16_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5009_50091202_17_dialog_content = "Para encontrar la verdad y perseguir al culpable, y para exigir venganza en nombre de su familia...",
  ui_story_5009_50091202_18_dialog_content = "Debes sentirte de una manera similar, PlayerName.",
  ui_story_5009_50091202_19_dialog_content = "Hay más que eso, mucho más que eso.",
  ui_story_5009_50091202_20_dialog_content = "¿No lo habían pensado, chicos? Si no hay nadie que detenga a estas personas o cambie las cosas para mejor ...",
  ui_story_5009_50091202_21_dialog_content = "Estas tragedias estarían condenadas a repetirse una y otra vez...",
  ui_story_5009_50091202_22_dialog_content = "Sin duda. Por lo tanto, debemos investigar el asunto de su pasado con claridad y encontrar la verdadera causa de esta lucha. Solo así evitaremos que vuelva a suceder.",
  ui_story_5009_50091202_23_dialog_content = "Pero si el problema está en la nobleza de Lumopolis... ¿Cómo lo arreglaremos entonces?",
  ui_story_5009_50091202_24_dialog_content = "Podemos responder preguntas en otro momento. En este momento, Mirren es nuestra principal prioridad.",
  ui_story_5009_50091202_25_dialog_content = "¡Aquí adentro!",
  ui_story_5009_50091202_26_dialog_content = "Estoy absolutamente seguro de ello... ¡Mirren está aquí!",
  ui_story_5009_50091202_27_dialog_content = "¡Espera! ¿Qué es ese sonido...?",
  ui_story_5009_50091202_28_dialog_content = "<color=#e8d9bb>¡Estruendo...!</color>",
  ui_story_5009_50091202_29_dialog_content = "¡Cuiden su equilibrio, todos!",
  ui_story_5009_50091202_30_dialog_content = "El terremoto se detuvo...",
  ui_story_5009_50091202_31_dialog_content = "¿Cómo están tan bien construidas estas estructuras subterráneas que puedan soportar un temblor como ese?",
  ui_story_5009_50091202_32_dialog_content = "Si se trata de una cueva formada de forma natural, me temo que lo más probable es que estemos atrapados dentro.",
  ui_story_5009_50091202_33_dialog_content = "¿Qué fue ese ruido?",
  ui_story_5009_50091202_34_dialog_content = "¡Viene del interior de las estructuras!",
  ui_story_5009_50091202_35_dialog_content = "PlayerName... Podría ser...?",
  ui_story_5009_50091202_36_dialog_content = "Sí... Puedo sentir a Paloma. Es muy probable...",
  ui_story_5009_50091202_37_dialog_content = "Que Paloma ya ha encontrado a Mirren.",
  ui_story_5009_50091301_A1_dialog_content = "Mmmmm ... ¡Poder! ¡Poder delicioso!",
  ui_story_5009_50091301_1_dialog_content = "<color=#e8d9bb>¡Estruendo...!</color>",
  ui_story_5009_50091301_A2_dialog_content = "¡Jajaja! Justo a tiempo.",
  ui_story_5009_50091301_2_dialog_content = "Mirren Gautier... No eres más que un gusano escondido y acobardado.",
  ui_story_5009_50091301_3_dialog_content = "¿Lo es? ¡Pero ni siquiera tendrás la oportunidad de ser un gusano!",
  ui_story_5009_50091301_4_dialog_content = "Ah...!",
  ui_story_5009_50091301_5_dialog_content = "Tómalo como mi complemento, eres impresionante, aguantar una pelea así hasta aquí.",
  ui_story_5009_50091301_6_dialog_content = "Pero las técnicas ocultas de True Order no son más que Luminatics de bajo nivel.",
  ui_story_5009_50091301_7_dialog_content = "No se parecen en nada a mi poder... Poder extraordinario que me otorgó mi maestro.",
  ui_story_5009_50091301_8_dialog_content = "Ejem... Este poder del que estás hablando ... ¿Solo se puede restaurar de una manera tan desagradable?",
  ui_story_5009_50091301_9_dialog_content = "¿Convertirse en un monstruo también le robó su sentido del gusto?",
  ui_story_5009_50091301_10_dialog_content = "No puedo imaginarme de qué otra manera podrías comer tantos de esos repugnantes Eclipsites.",
  ui_story_5009_50091301_11_dialog_content = "¿Oh? Parece que aún no te has dado cuenta, pero lo más delicioso del mundo ... ¡es el poder!",
  ui_story_5009_50091301_12_dialog_content = "¿Te importaría probar? Ah sí, lo puedo ver ahora...",
  ui_story_5009_50091301_13_dialog_content = "Si consumieras Darkflow, te volverías mucho más hermosa de lo que eres ahora...",
  ui_story_5009_50091301_14_dialog_content = "¿De verdad crees que todos los demás son como tú?",
  ui_story_5009_50091301_15_dialog_content = "Oh, solo quería darte una oportunidad, para pintar una imagen de lo que podrías ser ...",
  ui_story_5009_50091301_16_dialog_content = "¡Pero supongo que sería más fácil recolectar tus restos y hacer una muestra de ellos!",
  ui_story_5009_50091301_17_dialog_content = "¡Mira, es Mirren!",
  ui_story_5009_50091301_18_dialog_content = "Oh no... Paloma, ¡cuidado!",
  ui_story_5009_50091301_19_option_content = "¡Potencia de fuerza!",
  ui_story_5009_50091301_20_dialog_content = "¡Esquiva al revés!",
  ui_story_5009_50091301_21_dialog_content = "¡Gracias a Dios! ¡No pensé que Paloma evitaría ese último ataque!",
  ui_story_5009_50091301_22_dialog_content = "Aún así, ahora se ve completamente exhausta...",
  ui_story_5009_50091301_23_dialog_content = "*tos* PlayerName...",
  ui_story_5009_50091301_24_dialog_content = "¿Nunca pides permiso antes de usar tus habilidades psíquicas?",
  ui_story_5009_50091301_25_option_content = "Realmente no...",
  ui_story_5009_50091301_26_dialog_content = "¡Solo uso mis poderes así en caso de emergencias!",
  ui_story_5009_50091301_27_option_content = "No tenía otra opción...",
  ui_story_5009_50091301_28_dialog_content = "No se me permitió pensar mucho en una situación tan desesperada ...",
  ui_story_5009_50091301_29_dialog_content = "¿Oh? Entonces debería considerarme afortunado.",
  ui_story_5009_50091301_30_dialog_content = "¿Qué te tomó tanto tiempo? Te perdiste bastante la actuación hace un momento, ¿sabes?",
  ui_story_5009_50091301_31_dialog_content = "Aunque no importa, supongo. Eso es porque...",
  ui_story_5009_50091301_32_dialog_content = "¡El verdadero espectáculo está a punto de comenzar!",
  ui_story_5009_50091301_33_dialog_content = "¡Cuidado, todos!",
  ui_story_5009_50091301_34_dialog_content = "No este extraño espacio de nuevo...",
  ui_story_5009_50091301_35_dialog_content = "¿Llegamos demasiado tarde? Parece haber recuperado sus fuerzas. No puedo imaginar cuántos Eclipsites comió para recuperarse tanto...",
  ui_story_5009_50091301_36_dialog_content = "Fuera de mi camino.",
  ui_story_5009_50091301_37_dialog_content = "<color=#e8d9bb>¡Pam! ¡Pam! ¡Pam!</color>",
  ui_story_5009_50091301_38_dialog_content = "¡No puedo romperlo! ¿Realmente he gastado tanto poder...?",
  ui_story_5009_50091301_39_option_content = "Intenta sentir",
  ui_story_5009_50091301_40_dialog_content = "Déjame intentar de nuevo...",
  ui_story_5009_50091301_41_option_content = "¡Potencia de fuerza!",
  ui_story_5009_50091301_42_dialog_content = "PlayerName...",
  ui_story_5009_50091301_43_dialog_content = "Tu hab. psíquica no te servirá de mucho dentro de este espacio.",
  ui_story_5009_50091301_44_dialog_content = "Espera, déjame pensar... Tiene que haber algo que podamos hacer.",
  ui_story_5009_50091301_45_dialog_content = "¡Cuidado con los ataques del enemigo, todos!",
  ui_story_5009_50091301_46_dialog_content = "¡Shh! Calla.",
  ui_story_5009_50091301_47_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5009_50091301_48_dialog_content = "PlayerName! Encuentra una manera de salir de aquí; ¡Me defenderé de los ataques de Mirren!",
  ui_story_5009_50091301_49_dialog_content = "¡Lo tengo!",
  ui_story_5009_50091301_50_dialog_content = "¡Jajaja! Oh, Paloma ... Nunca pensé que seguirías siendo tan ingenuo después de todo.",
  ui_story_5009_50091301_51_dialog_content = "¡Intenta defenderte de mis ataques!",
  ui_story_5009_50091301_52_dialog_content = "Urgh...",
  ui_story_5009_50091301_53_dialog_content = "No podemos seguir así...",
  ui_story_5009_50091301_54_dialog_content = "¡Mirren! Soy el único representante de Lumopolis aquí, ¡no ellos! Si quieres descargar tu enojo con alguien, ¡hazlo conmigo! ¡Déjalos ir!",
  ui_story_5009_50091301_55_dialog_content = "¿Oh? Me parece haber escuchado algo bastante interesante.",
  ui_story_5009_50091301_56_dialog_content = "¿Qué fue eso ahora? ¿\"Déjalos ir? ¡Jajajaja! ¡No me hagas reír!",
  ui_story_5009_50091301_57_dialog_content = "¿Son las vidas de tus compañeros las únicas dignas de misericordia? ¿Dónde estaba esa misma misericordia cuando mi familia fue masacrada hace tantos años?",
  ui_story_5009_50091301_58_dialog_content = "Esto debe significar que las vidas de la familia de la señorita Paloma eran dignas de su misericordia. ¡¿Estoy equivocado?!",
  ui_story_5009_50091301_59_dialog_content = "Mirren Gautier... Tu familia era inocente, pero estás lejos de serlo.",
  ui_story_5009_50091301_60_dialog_content = "Decidiste convertirte en el autor de la violencia y, al hacerlo, condenaste a toda tu familia al sufrimiento y la muerte.",
  ui_story_5009_50091301_61_dialog_content = "Tus palabras ahora no son más que una pérdida de tiempo.",
  ui_story_5009_50091301_62_dialog_content = "Disparates... Son tus palabras las que no son nada, ¡no las mías!",
  ui_story_5009_50091301_63_dialog_content = "Nada más que una criatura egoísta ... ¡esto termina ahora!",
  ui_story_5009_50091301_64_dialog_content = "¡Jajaja! ¿Haciendo la vista gorda a la razón una vez más? Nuestras familias nunca se habrían exiliado si no fuera por esa tendencia suya.",
  ui_story_5009_50091301_65_dialog_content = "Antes no tenía poder y fui perseguido por ello.",
  ui_story_5009_50091301_66_dialog_content = "Pero una vez que lo adquirí, la gente me temió y me obedeció... E incluso me admiraba...",
  ui_story_5009_50091301_67_dialog_content = "Desafortunadamente, mi familia no entendió ni aceptó esto, por lo que Lumopolis se encargó de ellos.",
  ui_story_5009_50091301_68_dialog_content = "En cuanto a mí, disfruté mucho al ver tus rostros aterrorizados y santurrones mientras permaneces indefenso ante mi poder.",
  ui_story_5009_50091301_69_dialog_content = "Esta es mi justicia.",
  ui_story_5009_50091301_70_dialog_content = "Otro grandioso monólogo sobre el poder... Estoy tan harto de escucharlo.",
  ui_story_5009_50091301_71_dialog_content = "No tienes derecho a hablar de justicia en el momento en que vendes tu alma a cambio de poder.",
  ui_story_5009_50091301_72_dialog_content = "Y no hables de tu familia como si fuera otra cosa que herramientas a tus ojos.",
  ui_story_5009_50091301_73_dialog_content = "Mirren ... ¿siempre eres tan dramática o es otro resultado de tu transformación?",
  ui_story_5009_50091301_74_dialog_content = "¡Hah!",
  ui_story_5009_50091301_78_dialog_content = "Hmph, mi paciencia se ha agotado.",
  ui_story_5009_50091301_79_dialog_content = "¡Es hora de enviarlos a todos al infierno, con el resto de los Celestitas!",
  ui_story_5009_50091301_75_dialog_content = "PlayerName, sal del camino!",
  ui_story_5009_50091301_A3_dialog_content = "¡Sobre mi cadáver!",
  ui_story_5009_50091301_80_dialog_content = "¿Paloma? ¿Todavía puedes pelear?",
  ui_story_5009_50091301_82_dialog_content = "¡¿Qué?!",
  ui_story_5009_50091301_A4_dialog_content = "No te quedes ahí parado, trata de seguirme. Ataquemos juntos... ¡No pares hasta que esto termine!",
  ui_story_5009_50091301_A5_dialog_content = "Entonces, ¡realmente sabes lo que es el trabajo en equipo! ¡Soldados, síganme!",
  ui_story_5009_50091301_A6_dialog_content = "No tengo otra elección... ¡Flor de hielo!",
  ui_story_5009_50091301_A7_dialog_content = "¡Acepta tu juicio!",
  ui_story_5009_50091301_A8_dialog_content = "Así es, todos ... ¡No tomaremos esto tumbados!",
  ui_story_5009_50091301_76_dialog_content = "¡Hmph!",
  ui_story_5009_50091301_77_option_content = "¡Enlace mental!",
  ui_story_5009_50091301_A9_dialog_content = "Ay... Mi cabeza...",
  ui_story_5009_50091301_A10_dialog_content = "Pero este es un Eraveil ... No es...",
  ui_story_5009_50091301_A11_dialog_content = "¿Esto es en serio? ¡Mi control sobre Luminatics parece haber mejorado un poco!",
  ui_story_5009_50091301_A12_dialog_content = "Aquí igual.",
  ui_story_5009_50091301_A13_dialog_content = "Los ataques de todos están funcionando ... ¡Nos estamos liberando del control de este lugar!",
  ui_story_5009_50091301_81_dialog_content = "¡Mis habilidades psíquicas también han regresado ligeramente!",
  ui_story_5009_50091301_83_dialog_content = "Mirren Gautier... No importa lo que hayas hecho o el sufrimiento que hayas causado en el pasado...",
  ui_story_5009_50091301_84_dialog_content = "¡Trajiste destrucción a Eraveil en nombre de Eclipse!",
  ui_story_5009_50091301_85_dialog_content = "¡No te perdonaré por esto!",
  ui_story_5009_50091301_86_dialog_content = "¡Jajajaja! ¡Qué palabras tan fuertes de una criatura tan frágil!",
  ui_story_5009_50091301_87_dialog_content = "¡Muy bien! Si así debe ser... ¡Usaré todo mi poder para aplastarte!",
  ui_story_5009_50091301_88_dialog_content = "¡Graaaaaagh!",
  ui_story_5009_50091301_89_dialog_content = "¿Están todos listos? ¡Es hora de acabar con esto!",
  ui_story_5009_50091301_90_dialog_content = "Tus poderes psíquicos... ¿Se han recuperado?",
  ui_story_5009_50091301_91_dialog_content = "Hmph, estoy más listo que nunca. ¡Vamos!",
  ui_story_5009_50091301_92_option_content = "¡Activa poderes!",
  ui_story_5009_50091302_1_dialog_content = "La luz es tan brillante...",
  ui_story_5009_50091302_2_dialog_content = "El Eclipse comienza a desvanecerse.",
  ui_story_5009_50091302_3_dialog_content = "¡De nuevo! El escapó...",
  ui_story_5009_50091302_4_dialog_content = "Mirren Gautier ... es tan astuta como siempre.",
  ui_story_5009_50091302_5_dialog_content = "Una vez que las tornas comienzan a cambiar, usa todo su ingenio para escapar.",
  ui_story_5009_50091302_6_dialog_content = "Realmente lo hemos herido esta vez. Me temo que no volveremos a oír nada durante mucho tiempo.",
  ui_story_5009_50091302_7_dialog_content = "Mirren Gautier... ¿Vino a Eraveil hace diecisiete años?",
  ui_story_5009_50091302_8_dialog_content = "¿Por qué preguntas?",
  ui_story_5009_50091302_9_dialog_content = "Hace diecisiete años, cuando Eraveil y los Celestitas fueron aniquilados... Hubo un eclipse en el cielo, como hoy.",
  ui_story_5009_50091302_10_dialog_content = "Pensé que tal vez había ...",
  ui_story_5009_50091302_11_dialog_content = "Lo siento, pero como he sabido ...",
  ui_story_5009_50091302_12_dialog_content = "Antes de que nuestras familias fueran exiliadas y enviadas a la Baja Lumopolis, no creo que Mirren haya salido nunca de Lumopolis.",
  ui_story_5009_50091302_13_dialog_content = "¿Cuándo exactamente fueron exiliadas sus familias?",
  ui_story_5009_50091302_14_dialog_content = "Hace doce años.",
  ui_story_5009_50091302_15_dialog_content = "Así que... ¿No fue él?",
  ui_story_5009_50091302_16_dialog_content = "Por lo que reunimos, creo...",
  ui_story_5009_50091302_17_dialog_content = "Es más probable que el supuesto maestro de Mirren haya estado involucrado.",
  ui_story_5009_50091302_18_dialog_content = "¡...!",
  ui_story_5009_50091302_19_dialog_content = "¿Cuánto sabes realmente sobre Eclipse, Paloma?",
  ui_story_5009_50091302_20_dialog_content = "¡Me gustaría preguntar lo mismo!",
  ui_story_5009_50091302_21_dialog_content = "La aparición de Eclipse ... es probablemente un poder que posee su organización.",
  ui_story_5009_50091302_22_dialog_content = "En las áreas afectadas por el Eclipse, las Luminarias de otros se debilitan en diversos grados.",
  ui_story_5009_50091302_23_dialog_content = "Mi capacidad psíquica también se vio afectada desde el principio ...",
  ui_story_5009_50091302_24_dialog_content = "¿Qué pasa con ese extraño espacio justo ahora? ¿Qué era?",
  ui_story_5009_50091302_25_dialog_content = "Era algo así como una zona de Eclipse sellada y concentrada, donde sus efectos de debilitamiento son aún más pronunciados.",
  ui_story_5009_50091302_26_dialog_content = "Salir de ese espacio desde adentro es extremadamente difícil, pero destruirlo desde afuera es mucho más fácil.",
  ui_story_5009_50091302_27_dialog_content = "En cuanto al maestro ...",
  ui_story_5009_50091302_28_dialog_content = "Mi pueblo ... ¿Los celestitas fueron destruidos por el mismo tipo de ataque?",
  ui_story_5009_50091302_29_dialog_content = "¿Cómo sabes tanto sobre Mirren Gautier, Paloma? ¿O sobre cómo funciona el Eclipse?",
  ui_story_5009_50091302_30_dialog_content = "¿Oh? ¿Sospechas de mi ahora?",
  ui_story_5009_50091302_31_dialog_content = "M-Mis disculpas.",
  ui_story_5009_50091302_32_dialog_content = "Simplemente tengo curiosidad. ¿Por qué sus poderes no se vieron afectados por el Eclipse?",
  ui_story_5009_50091302_33_dialog_content = "Cuando estás impulsado por una sed de venganza, no notas mucho fuera de eso.",
  ui_story_5009_50091302_34_dialog_content = "Es solo un precio que debo pagar. Temo que nunca lo entiendas.",
  ui_story_5009_50091302_35_dialog_content = "¿También buscas venganza contra Lumopolis?",
  ui_story_5009_50091302_36_dialog_content = "Oh, parece ser más consciente de lo que creí, princesa de Lumopolis ...",
  ui_story_5009_50091302_37_dialog_content = "Pon tu mente en paz. No es hora de Lumopolis ... todavía.",
  ui_story_5009_50091302_38_dialog_content = "Entonces debes saber que no permitiré que ningún daño venga a Lumopolis ni a su gente.",
  ui_story_5009_50091302_39_dialog_content = "Hmm. Tendremos que esperar y ver entonces, ¿no?",
  ui_story_5009_50091302_40_dialog_content = "Venganza...",
  ui_story_5009_50091302_41_dialog_content = "No sé los demás... Pero estoy seguro de que entiendes muy bien el sentimiento, PlayerName.",
  ui_story_5009_50091302_42_dialog_content = "... ¿Elegirías convertirte en un Eclipsite solo por tu venganza?",
  ui_story_5009_50091302_43_dialog_content = "Tu broma es un poco mala para mi gusto. PlayerName.",
  ui_story_5009_50091302_44_dialog_content = "Déjame preguntarte lo mismo, ¿te convertirías en un Eclipsite solo por venganza?",
  ui_story_5009_50091302_45_dialog_content = "¡Claro que no!",
  ui_story_5009_50091302_46_dialog_content = "¡Entonces somos iguales!",
  ui_story_5009_50091302_47_dialog_content = "Jajaja... Siento que tenemos mucho más en común, PlayerName. Sin embargo...",
  ui_story_5009_50091302_48_dialog_content = "También siento que charlar así es una pérdida de tiempo. Debería irme ahora.",
  ui_story_5009_50091302_49_dialog_content = "Paloma.",
  ui_story_5009_50091302_50_dialog_content = "Tú y Beryl...",
  ui_story_5009_50091302_51_dialog_content = "Ah... sé lo que estás tratando de preguntar, PlayerName.",
  ui_story_5009_50091302_52_dialog_content = "Mi venganza no tiene nada que ver con Beryl.",
  ui_story_5009_50091302_53_dialog_content = "Entonces ella ... ¿está bien?",
  ui_story_5009_50091302_54_dialog_content = "Hmph, ¿no están trabajando juntos para reconstruir el Correo?",
  ui_story_5009_50091302_55_dialog_content = "Si realmente quieres saberlo, escríbele una carta y pregúntale tú mismo.",
  ui_story_5009_50091302_56_dialog_content = "Me voy ahora.",
  ui_story_5009_50091302_57_dialog_content = "Espere, señorita Paloma.",
  ui_story_5009_50091302_58_dialog_content = "¿Qué? ¿Estás pensando en arrestarme antes de que me escape?",
  ui_story_5009_50091302_59_dialog_content = "Deseo reabrir la investigación sobre las familias Pyrrhus y Gautier y seguir investigando el asunto.",
  ui_story_5009_50091302_60_dialog_content = "Naturalmente, si regresara conmigo al Salón de Justicia...",
  ui_story_5009_50091302_61_dialog_content = "¿Y qué? ¿Darle la oportunidad de cumplir con sus deberes capturándome?",
  ui_story_5009_50091302_62_dialog_content = "¡Por favor, Paloma! ¡Sabes que no soy ese tipo de persona!",
  ui_story_5009_50091302_63_dialog_content = "Quiero saber la verdad, para que podamos dejar las cosas claras.",
  ui_story_5009_50091302_64_dialog_content = "¿Es eso así? Entonces déjame preguntarte algo, ¿sabes por qué las élites de Lumopolis optaron por ocultar la verdad?",
  ui_story_5009_50091302_65_dialog_content = "¿Sabes quién estuvo detrás de todo esto?",
  ui_story_5009_50091302_66_dialog_content = "No, no lo sabes.",
  ui_story_5009_50091302_67_dialog_content = "Correcto. No lo sé y no necesito saberlo.",
  ui_story_5009_50091302_68_dialog_content = "Solo necesito saber que mi papel es investigar la verdad.",
  ui_story_5009_50091302_69_dialog_content = "... ¿Ah?",
  ui_story_5009_50091302_70_dialog_content = "En ese entonces, varios colegas y yo fuimos enviados a Umbraton para investigar el asunto, pero en cambio nos encontramos con miembros de Eclipse...",
  ui_story_5009_50091302_71_dialog_content = "*Tosiendo* ¿Estás bien ...?",
  ui_story_5009_50091302_72_dialog_content = "Pittman... Mis piernas ya no son buenas...",
  ui_story_5009_50091302_73_dialog_content = "Pero tú ... y los demás ...",
  ui_story_5009_50091302_74_dialog_content = "Si sigues perdiendo el tiempo, ¡todos vamos a ser eliminados!",
  ui_story_5009_50091302_75_dialog_content = "¡Ahora vete!",
  ui_story_5009_50091302_76_dialog_content = "Sus padres e hijos, esposos y esposas...",
  ui_story_5009_50091302_77_dialog_content = "Como único superviviente del ataque, les debo a todos una explicación por la muerte de sus seres queridos.",
  ui_story_5009_50091302_78_dialog_content = "Creo que ahora entiendo un poco mejor tus sentimientos... Pero, señoría, ¡detenga estos pensamientos santurrones!",
  ui_story_5009_50091302_79_dialog_content = "Con su puesto actual, nunca podrá encontrar la verdad.",
  ui_story_5009_50091302_80_dialog_content = "El Dios de la Luz me ha confiado esta tarea. No puedo y no fallaré en mis deberes.",
  ui_story_5009_50091302_81_dialog_content = "La justicia puede tardar mucho en hacerse, ¡pero algún día se cumplirá!",
  ui_story_5009_50091302_82_dialog_content = "......",
  ui_story_5009_50091302_83_dialog_content = "*Suspiro* En ese caso, todo lo que puedo hacer...",
  ui_story_5009_50091302_84_dialog_content = "Te deseo suerte.",
  ui_story_5009_50091302_85_dialog_content = "Hasta que nos encontremos de nuevo, PlayerName!",
  ui_story_5009_50091302_86_dialog_content = "Paloma! ¡Espera!",
  ui_story_5009_50091302_87_dialog_content = "......",
  ui_story_5009_50091302_88_dialog_content = "¿Está realmente bien... Dejar ir a un fugitivo así?",
  ui_story_5009_50091302_89_dialog_content = "No nos involucremos.",
  ui_story_5009_50091302_90_dialog_content = "¿Qué le dirás a tus superiores, Pittman?",
  ui_story_5009_50091302_91_dialog_content = "La verdad, Lady Carleen. Les informaré de la verdad indiscutible.",
  ui_story_5009_50091302_92_dialog_content = "¿Pero no le preocupa que el Salón de Justicia lo culpe por dejar escapar a un fugitivo?",
  ui_story_5009_50091302_93_dialog_content = "Parece que varios casos de la última década fueron más complejos de lo que parecían y ameritan una mayor investigación.",
  ui_story_5009_50091302_94_dialog_content = "Creo que el Salón de Justicia, así como el Juez Principal, no ignorarán la necesidad de aclarar estos casos, y mucho menos castigarme sin una buena causa.",
  ui_story_5009_50091302_95_dialog_content = "En el nombre del Dios de la Luz, juro que encontraré la verdad, sin importar el precio que deba pagar.",
  ui_story_5009_50091302_96_dialog_content = "Lumopolis tiene la suerte de tener un juez como usted. Creo en tu causa.",
  ui_story_5009_50091302_97_dialog_content = "Yo... ¡Yo también creo en ti, Pittman!",
  ui_story_5009_50091302_98_dialog_content = "*se aclara la garganta* Oye, PlayerName!",
  ui_story_5009_50091302_99_dialog_content = "¿Todavía recuerdas lo que vinimos a hacer, en primer lugar?",
  ui_story_5009_50091302_100_option_content = "Recuerdo...",
  ui_story_5009_50091302_101_dialog_content = "Vinimos a ver Eraveil.",
  ui_story_5009_50091302_102_option_content = "Lo olvide por completo...",
  ui_story_5009_50091302_103_dialog_content = "*Suspiro* ¿No vinimos aquí para ayudar a reconstruir el puesto?",
  ui_story_5009_50091302_104_dialog_content = "Me pregunto si Naroxel y los demás se vieron afectados por el Eclipse.",
  ui_story_5009_50091302_105_dialog_content = "No me preocuparía demasiado por eso.",
  ui_story_5009_50091302_106_dialog_content = "Las comunicaciones están de nuevo en línea y, a juzgar por los mensajes de terminal que envió ...",
  ui_story_5009_50091302_107_dialog_content = "Parece que se mantienen muy ocupados.",
  ui_story_5009_50091302_108_dialog_content = "En ese caso, todavía no podemos permitirnos descansar.",
  ui_story_5009_50091302_109_dialog_content = "¿Hay algún Eclipsites escondido en Eraveil, PlayerName?",
  ui_story_5009_50091302_110_dialog_content = "Sí... Puedo sentir que todavía hay algunos Eclipsites de bajo nivel acechando en las cercanías.",
  ui_story_5009_50091302_111_dialog_content = "Entonces enviémoslos rápidamente y acabemos con esto.",
  ui_story_5009_50091302_112_dialog_content = "¡Acabemos con todos antes de que se ponga el sol, todos!",
  ui_story_5009_50091302_113_dialog_content = "¡Vamos!",
  ui_story_5009_50091302_114_dialog_content = "Ugh...",
  ui_story_5009_50091302_115_dialog_content = "Ustedes van por el camino equivocado... ¡Los Eclipsites están ahí!",
  ui_story_5009_50091401_1_dialog_content = "Parece que pronto oscurecerá.",
  ui_story_5009_50091401_2_dialog_content = "informe de estado, PlayerName?",
  ui_story_5009_50091401_3_dialog_content = "Eraveil es...",
  ui_story_5009_50091401_4_dialog_content = "Todavía quedan algunos, ¿eh? En serio ... ¡no hay forma de deshacerse de ellos!",
  ui_story_5009_50091401_5_dialog_content = "¿Dónde están los demás? ¡No pueden esconderse de mí!",
  ui_story_5009_50091401_6_dialog_content = "¡No siento ninguna Eclipsite en Eraveil!",
  ui_story_5009_50091401_7_dialog_content = "¡Te lo dije! ¡Sabía que podríamos limpiarlos antes de la puesta del sol!",
  ui_story_5009_50091401_8_dialog_content = "Bien hecho a todos. Todo es posible, siempre y cuando nunca nos demos por vencidos.",
  ui_story_5009_50091401_9_dialog_content = "¿Se han ido todos los Eclipsites?",
  ui_story_5009_50091401_10_dialog_content = "Espera ... ¿ganamos?",
  ui_story_5009_50091401_11_dialog_content = "Sí, lo hicimos ... y todo fue gracias a la ayuda de todos.",
  ui_story_5009_50091401_12_dialog_content = "¡Sí! ¡Ganamos!",
  ui_story_5009_50091401_13_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_5009_50091401_14_dialog_content = "¿Mmm? Espera... ¿Qué es ese sonido?",
  ui_story_5009_50091401_15_dialog_content = "Oh, eso es solo el sonido de notificación de mi terminal.",
  ui_story_5009_50091401_16_dialog_content = "L-Lo siento, déjame ver quién es realmente rápido...",
  ui_story_5009_50091401_17_dialog_content = "Saludos, Vice.",
  ui_story_5009_50091401_18_dialog_content = "¡Es Naroxel!",
  ui_story_5009_50091401_19_dialog_content = "¡Hola, Naroxel! ¿Cómo estás?",
  ui_story_5009_50091401_20_dialog_content = "¿Vaya? Parece que PlayerName está contigo, también.",
  ui_story_5009_50091401_21_dialog_content = "¿Cuál es tu estatus en Eraveil? ¿El área todavía está llena de actividad Eclipsite?",
  ui_story_5009_50091401_22_dialog_content = "¡Oh, no te preocupes! ¡Gracias a la ayuda de todos, hemos eliminado los eclipsitas en Eraveil!",
  ui_story_5009_50091401_23_dialog_content = "¡Gracias a las bendiciones de la naturaleza! Estaba más que preocupado por tu bienestar al principio ...",
  ui_story_5009_50091401_24_dialog_content = "Pero escucharte sonar lleno de energía me ha tranquilizado.",
  ui_story_5009_50091401_25_dialog_content = "De hecho, ha sido ... un día bastante largo. ¿Cómo van las cosas de tu lado? ¿Algún problema importante?",
  ui_story_5009_50091401_26_dialog_content = "Todo avanza sin problemas... Pero la enfermedad de Dove sigue siendo motivo de preocupación.",
  ui_story_5009_50091401_27_dialog_content = "Espera... ¿Dove realmente apareció?",
  ui_story_5009_50091401_28_dialog_content = "Sí, pero estaba muy enferma y era obvio para todos que necesitaba descansar. Hice los arreglos para que un vehículo de transporte la llevara de regreso lo antes posible.",
  ui_story_5009_50091401_29_dialog_content = "*Suspiro* Me pregunto si esa palomita solo está fingiendo para volver a salir del trabajo...",
  ui_story_5009_50091401_30_dialog_content = "Lo dudo, ya que parece que su enfermedad fue causada por un esfuerzo excesivo en este trabajo.",
  ui_story_5009_50091401_31_dialog_content = "No sabía que Dove pudiera esforzarse con regularidad en su trabajo...",
  ui_story_5009_50091401_32_dialog_content = "Ella realmente ayudó mucho hoy. Vengan y compruébenlo ustedes mismos, sabrán a qué me refiero.",
  ui_story_5009_50091401_33_dialog_content = "¿Ah? Bien, entonces.",
  ui_story_5009_50091401_34_dialog_content = "Ah, y Tweety quiere que te diga que te espera una gran sorpresa en el puesto.",
  ui_story_5009_50091401_35_dialog_content = "Aunque... ¿No les habla de ello contra el propósito de una sorpresa?",
  ui_story_5009_50091401_36_dialog_content = "En cualquier caso, todos deben estar agotados después de un día tan largo.",
  ui_story_5009_50091401_37_dialog_content = "Hemos preparado té caliente y bocadillos para ustedes en el Correo, para darles la bienvenida.",
  ui_story_5009_50091401_38_dialog_content = "¡Entendido! Pronto estaremos en camino. ¡Nos vemos pronto!",
  ui_story_5009_50091401_39_dialog_content = "Me pregunto qué quiso decir con una gran sorpresa.",
  ui_story_5009_50091401_40_dialog_content = "No estoy seguro, pero ella siempre ha tenido la habilidad de hacer lo inesperado. ¡Estoy emocionado de ver qué es!",
  ui_story_5009_50091401_41_dialog_content = "Solo espero que sea una buena sorpresa y no impactante.",
  ui_story_5009_50091401_42_dialog_content = "Ahora que Eraveil ha sido purgado de todas las amenazas de Eclipsite...",
  ui_story_5009_50091401_43_dialog_content = "Su Alteza, PlayerName, Vice... Creo que es hora de que regrese a Lumopolis para hacer mi informe.",
  ui_story_5009_50091401_44_dialog_content = "¿Qué? ¿Se van tan pronto?",
  ui_story_5009_50091401_45_dialog_content = "Vamos, Pittman. Estoy seguro de que el Salón de Justicia será más que comprensivo si te quedas un poco más.",
  ui_story_5009_50091401_46_dialog_content = "No hay necesidad de tener tanta prisa.",
  ui_story_5009_50091401_47_dialog_content = "¡Es correcto! Sin mencionar que aún no ha tratado sus lesiones a partir de hoy ...",
  ui_story_5009_50091401_48_dialog_content = "¿Por qué no quedarse con nosotros y descansar un poco? ¡Me sentiría honrado de tenerte como nuestro invitado!",
  ui_story_5009_50091401_49_dialog_content = "Gracias a todos por su amable hospitalidad, pero me temo que debo negarme respetuosamente.",
  ui_story_5009_50091401_50_dialog_content = "Soportar esta tormenta con todos ustedes me ha dado mucho en qué pensar ... y ha fortalecido mi propia determinación.",
  ui_story_5009_50091401_51_dialog_content = "Gracias a todos ustedes, he reunido muchos conocimientos y obtenido muchas pistas de investigación aquí en Eraveil.",
  ui_story_5009_50091401_52_dialog_content = "Deseo presentar mi informe a toda prisa y continuar con el siguiente paso de mi investigación.",
  ui_story_5009_50091401_53_dialog_content = "Si su corazón está realmente puesto en ello, entonces entendemos...",
  ui_story_5009_50091401_54_dialog_content = "Pero cuando tengas tiempo libre, recuerda venir a vernos de nuevo, ¿de acuerdo?",
  ui_story_5009_50091401_55_dialog_content = "Por supuesto, PlayerName. Tengo un presentimiento...",
  ui_story_5009_50091401_56_dialog_content = "Que nos volveremos a ver muy pronto.",
  ui_story_5009_50091401_57_dialog_content = "¿Cómo pueden estos tipos entrar y salir cuando les plazca?",
  ui_story_5009_50091401_58_dialog_content = "Siento que no deberíamos estar aquí, pero ver cómo se desarrolla el drama es algo entretenido, ¿eh?",
  ui_story_5009_50091401_59_dialog_content = "¡Ejem! ¿Hay algo que deseen compartir con nosotros, soldados?",
  ui_story_5009_50091401_60_dialog_content = "¡N-No, señora!",
  ui_story_5009_50091401_61_dialog_content = "¡E-Estábamos discutiendo cuál es la mejor manera de regresar!",
  ui_story_5009_50091401_62_dialog_content = "Si a nadie le importa, ¿puedo llevar a todos de regreso en el Colossus?",
  ui_story_5009_50091401_63_dialog_content = "Sin embargo, solo tengo una condición.",
  ui_story_5009_50091401_64_dialog_content = "¿Una condición? ¡Estaban aquí para ayudar! ¿No crees que se acabó demasiado para pedir una condición?",
  ui_story_5009_50091401_65_dialog_content = "¡Primero escucha lo que tengo que decirte, Vice!",
  ui_story_5009_50091401_66_dialog_content = "¿Cuál es tu condición? Estamos escuchando.",
  ui_story_5009_50091401_67_dialog_content = "Son todos mis primeros huéspedes que traigo de vuelta a Eraveil, mi tierra natal ...",
  ui_story_5009_50091401_68_dialog_content = "Pero después de todo lo que hemos pasado hoy y toda la ayuda que nos has brindado, siento que he sido un anfitrión terrible ...",
  ui_story_5009_50091401_69_dialog_content = "Así que me gustaría preguntarles a todos... ¿Podrían darme otra oportunidad para tratarlos a todos como mis invitados y ser un anfitrión adecuado?",
  ui_story_5009_50091401_70_dialog_content = "¿Eso es todo? ¡Jajaja! ¡No tengo ninguna objeción aquí! ¿Y ustedes, chicos?",
  ui_story_5009_50091401_71_dialog_content = "¡Me suena bien! ¡Finalmente, un poco de descanso! ¡Está bien!",
  ui_story_5009_50091401_72_dialog_content = "Lo siento, PlayerName... Supongo que salté a la conclusión equivocada.",
  ui_story_5009_50091401_73_dialog_content = "Pero, ¿exactamente cómo planeas tratar a todos?",
  ui_story_5009_50091401_74_dialog_content = "Bueno en realidad... Hace unos días decidí prepararme para el Día de Windland...",
  ui_story_5009_50091401_75_dialog_content = "Pedí muchos bocadillos y bebidas a través de Unión de mensajería. Deberían llegar mañana en algún momento.",
  ui_story_5009_50091401_76_dialog_content = "PlayerName... ¿Se te ocurrió mirar la hoja de gastos del Colossus antes de ordenar algo?",
  ui_story_5009_50091401_77_dialog_content = "D-De todos modos... Realmente deberíamos volver al Correo primero, ¿no crees? Naroxel todavía nos espera, ¡lo sabes!",
  ui_story_5009_50091401_78_dialog_content = "¡Incluso nos prepararon té y bocadillos!",
  ui_story_5009_50091401_79_dialog_content = "¡Sí! ¡Vamos!",
  ui_story_5009_50091401_80_dialog_content = "<color=#e8d9bb> Gruñido ... </color>",
  ui_story_5009_50091401_81_dialog_content = "¡Espera! ¡Creo que escuché el sonido de un Eclipsite hace un momento!",
  ui_story_5009_50091401_82_dialog_content = "¿Puedes sentir algo, PlayerName?",
  ui_story_5009_50091401_83_dialog_content = "Oh... Lo siento, creo que eso fue mi estómago refunfuñando...",
  ui_story_5009_50091401_84_dialog_content = "Una falsa alarma...",
  ui_story_5009_50091401_85_dialog_content = "Como no hay nada de qué preocuparse, deberíamos acelerar un poco más el ritmo.",
  ui_story_5009_50091401_86_dialog_content = "Estamos casi en el puesto, ¡así que no los hagamos esperar!",
  ui_story_5009_50091401_87_dialog_content = "Okey... Aunque no diría que mi estómago vacío no es nada de qué preocuparse ...",
  ui_story_5009_50091401_88_dialog_content = "¿Puedes seguir caminando, PlayerName? ¿O debo hacer que Bessie te lleve de regreso?",
  ui_story_5009_50091401_89_dialog_content = "¡¿N-Naroxel?! ¿Has estado aquí todo este tiempo?",
  ui_story_5009_50091401_90_dialog_content = "Lo siento, ¿te asusté?",
  ui_story_5009_50091401_91_dialog_content = "Tweety estaba empezando a preocuparse porque estabas tardando tanto, así que me pidió que fuera a buscarte.",
  ui_story_5009_50091401_92_dialog_content = "Escuché tu comentario justo cuando los encontré a todos...",
  ui_story_5009_50091401_93_dialog_content = "No es gran cosa, de verdad...",
  ui_story_5009_50091401_94_dialog_content = "¡Qué considerado de tu parte, Naroxel, Tweety!",
  ui_story_5009_50091401_95_dialog_content = "Excepto... ¿No veo a Tweety por ningún lado?",
  ui_story_5009_50091401_96_dialog_content = "¿Quizás le tiene miedo a la oscuridad?",
  ui_story_5009_50091401_97_dialog_content = "No, es solo que ... alguien tuvo que quedarse y vigilar el Correo, eso es todo.",
  ui_story_5009_50091401_98_dialog_content = "Me parece que está ocupada preparando su legendaria gran sorpresa.",
  ui_story_5009_50091401_99_dialog_content = "De todos modos... ¡Por aquí todos!",
  ui_story_5009_50091401_100_dialog_content = "<color=#e8d9bb>Creeeak...</color>",
  ui_story_5009_50091401_101_dialog_content = "Guau...!",
  ui_story_5009_50091401_102_dialog_content = "Esos estantes y ese mostrador... Todos parecen tan familiares.",
  ui_story_5009_50091401_103_dialog_content = "Si no me equivoco, el puesto de Lumopolis está diseñado de manera similar.",
  ui_story_5009_50091401_104_dialog_content = "Pero aun así, este buzón es completamente diferente. De alguna manera me recuerda a Soroz...",
  ui_story_5009_50091401_105_dialog_content = "Eso es correcto. Este es el buzón de autoservicio del puesto de Eraveil, diseñado por los propios Celestitas.",
  ui_story_5009_50091401_106_dialog_content = "Afortunadamente, todavía está operativo después de todo este tiempo.",
  ui_story_5009_50091401_107_dialog_content = "¡Oye, mira lo que encontré en este estante de aquí!",
  ui_story_5009_50091401_108_dialog_content = "Postales ... ¡de hace diez años! ¡Solo he visto algo así en el museo!",
  ui_story_5009_50091401_109_dialog_content = "¡E incluso hay un acuario aquí!",
  ui_story_5009_50091401_110_dialog_content = "¡Deje que Naroxel lleve el espíritu de la naturaleza a un lugar como este!",
  ui_story_5009_50091401_111_dialog_content = "Sobre ese tema, Dove dedicó mucho tiempo y energía a conseguir los peces que ve dentro del acuario.",
  ui_story_5009_50091401_112_dialog_content = "¿Dove? Nunca hubiera imaginado...",
  ui_story_5009_50091401_113_dialog_content = "Estoy tan celoso de ti, PlayerName! ¡Ninguna de las publicaciones en la Federación Illumina es tan acogedora como esta!",
  ui_story_5009_50091401_114_dialog_content = "¿Mmm? ¿Por qué no dices nada? PlayerName?",
  ui_story_5009_50091401_115_dialog_content = "Yo... Me siento realmente emocionado. Tan emocionado ... que realmente no sé cómo expresar mis sentimientos en este momento.",
  ui_story_5009_50091401_116_dialog_content = "Esta es ... la primera habitación en Eraveil que tiene luces.",
  ui_story_5009_50091401_117_dialog_content = "Y ha sido decorado tan bellamente... ¿Es esto realmente solo una puesto?",
  ui_story_5009_50091401_118_dialog_content = "Me encantaría vivir aquí, si estuviera permitido...",
  ui_story_5009_50091401_119_dialog_content = "¡Miaauu!",
  ui_story_5009_50091401_120_dialog_content = "¡Jaja! Lo sentimos, parece que no serás el primer residente aquí.",
  ui_story_5009_50091401_121_dialog_content = "Sabes, PlayerName, si realmente quisieras vivir aquí... ¡Serías bienvenido a hacerlo, como empleado del Sindicato de Mensajeros!",
  ui_story_5009_50091401_122_dialog_content = "Pero antes de nada de eso... ¿Aún recuerdas esta carta de aceptación?",
  ui_story_5009_50091401_123_dialog_content = "Lo hago, es solo...",
  ui_story_5009_50091401_124_dialog_content = "No creo que pueda hacer ni cara ni cruz, estoy demasiado cansada para leer ahora.",
  ui_story_5009_50091401_125_dialog_content = "Tal vez podrías dar PlayerName los puntos principales de la carta, Naroxel? ¿Estaría bien?",
  ui_story_5009_50091401_126_dialog_content = "No es un problema. Si la reconstrucción de este puesto por parte de Unión de Mensajería ha cumplido adecuadamente sus expectativas laborales...",
  ui_story_5009_50091401_127_dialog_content = "De hecho, superó mis expectativas... ¡Aproximadamente cien veces más!",
  ui_story_5009_50091401_128_dialog_content = "Gracias por su aporte. Entonces, si lo desea, firme con su nombre a continuación y recuerde ...",
  ui_story_5009_50091401_129_dialog_content = "Una vez que haya completado su firma, su contrato con nuestras Publicaciones entrará en vigor oficialmente.",
  ui_story_5009_50091401_130_dialog_content = "¿Qué quiere decir exactamente con oficialmente en vigor?",
  ui_story_5009_50091401_131_dialog_content = "Dentro de la red de transporte de Unión de mensajería, el hito de Eraveil Correo volverá a iluminarse.",
  ui_story_5009_50091401_132_dialog_content = "En otras palabras, Eraveil podrá recibir correos de todo el mundo.",
  ui_story_5009_50091401_133_dialog_content = "(Antes del desastre ... la gente de Eraveil vino aquí para recibir cartas de Illumina y Lumopolis ...)",
  ui_story_5009_50091401_134_dialog_content = "(¿E incluso Northland?)",
  ui_story_5009_50091401_135_dialog_content = "(Eso significa... Que los Celestitas también usaban este lugar...)",
  ui_story_5009_50091401_136_dialog_content = "(¿Para enviar mensajes al mundo también? ¿Cartas con su alegría y tristeza?)",
  ui_story_5009_50091401_137_dialog_content = "(Si firmo con mi nombre, esta publicación volverá a ser como era ... hace diecisiete años).",
  ui_story_5009_50091401_138_dialog_content = "(Si firmo mi nombre, Eraveil volverá a la vida en todos los mapas del mundo...)",
  ui_story_5009_50091401_139_dialog_content = "¿Todavía tiene alguna pregunta o inquietud, PlayerName?",
  ui_story_5009_50091401_140_dialog_content = "No, solo necesito saber dónde firmar mi nombre. Voy a...",
  ui_story_5009_50091401_141_dialog_content = "¡Devolverle la vida a Eraveil!",
  ui_story_5009_50091401_142_dialog_content = "Aquí mismo, si lo deseas. ¡No creo haber visto a alguien tan emocionado por firmar un contrato antes!",
  ui_story_5009_50091401_143_dialog_content = "Firma:",
  ui_story_5009_50091401_A1_dialog_content = "...",
  ui_story_5009_50091401_144_option_content = "PlayerName",
  ui_story_5009_50091401_145_dialog_content = "<color=#e8d9bb>Gong... Gong... Gong...</color>",
  ui_story_5009_50091401_146_dialog_content = "¿Ya es medianoche?",
  ui_story_5009_50091401_147_dialog_content = "No me di cuenta de que se había hecho tan tarde...",
  ui_story_5009_50091401_148_dialog_content = "Ya es mañana... Eso significa que es hora de...",
  ui_story_5009_50091401_149_dialog_content = "Urgh...",
  ui_story_5009_50091401_150_dialog_content = "¿Ah? Carleen, ¡cuidado!",
  ui_story_5009_50091401_151_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_5009_50091401_152_dialog_content = "Es esto... ¿Soroz?",
  ui_story_5009_50091401_153_dialog_content = "Pero el material ... ¡Es una muñeca de Soroz!",
  ui_story_5009_50091401_154_dialog_content = "Su... Tan... ¡Lindo! ¿De dónde vino esto?",
  ui_story_5009_50091401_155_dialog_content = "Esta debería ser la sorpresa de la que Tweety estaba hablando. Terminó siendo una sorpresa impactante, después de todo...",
  ui_story_5009_50091401_156_dialog_content = "¡Finalmente ustedes me notan!",
  ui_story_5009_50091401_157_dialog_content = "¿Eh? ¿Ese era Tweety? Escuché su voz, pero no la veo por ningún lado...",
  ui_story_5009_50091401_158_dialog_content = "Estoy aquí arriba ... ¡Quedé atrapado en el hielo de Carween!",
  ui_story_5009_50091401_159_dialog_content = "No tuve elección. Tenía miedo de que Tweety se cayera también ... Déjame deshacer la congelación.",
  ui_story_5009_50091401_160_dialog_content = "¡Gracias, Carween! Pero ... ¿olvidaste que tengo alas?",
  ui_story_5009_50091401_161_dialog_content = "Pero ser así como eso ... ¡se siente bien!",
  ui_story_5009_50091401_162_dialog_content = "Entonces, ¿te gustaría que te congelara de nuevo?",
  ui_story_5009_50091401_163_dialog_content = "¡N-No, gracias! Una vez es suficiente...",
  ui_story_5009_50091401_164_dialog_content = "¿Estuviste esperando en las vigas todo este tiempo, Tweety?",
  ui_story_5009_50091401_165_dialog_content = "¡Sí! ¡Estuve esperando a todos durante mucho tiempo!",
  ui_story_5009_50091401_166_dialog_content = "¡De esa manera, podría lanzarme con mi gran sodpresa!",
  ui_story_5009_50091401_167_dialog_content = "Pero... Me quedé dodmido por accidente... Y la campana me despertó hace un momento...",
  ui_story_5009_50091401_168_dialog_content = "Sowwy, PlayerName... Mi gran sorpresa fue una gran decepción...",
  ui_story_5009_50091401_169_dialog_content = "¡No tienes por qué disculparte, Tweety! Hiciste que este lugar se viera increíble ... Ni siquiera tuve tiempo de agradecérselo adecuadamente.",
  ui_story_5009_50091401_170_dialog_content = "Además, la campana de medianoche acaba de sonar, lo que significa que hoy es oficialmente el Festival de Windland.",
  ui_story_5009_50091401_171_dialog_content = "Los libros dicen que en esta festividad, los Celestitas también colgarían muñecos como este.",
  ui_story_5009_50091401_172_dialog_content = "¡Esta sorpresa tuya es absolutamente perfecta para la ocasión!",
  ui_story_5009_50091401_173_dialog_content = "¿D-De veddad? ¡Estoy muy feliz de escuchar eso!",
  ui_story_5009_50091401_174_dialog_content = "Así que realmente te gusta mi sorpresa, PlayerName?",
  ui_story_5009_50091401_175_dialog_content = "¡Por supuesto que sí! Pero, ¿dónde encontraste algo como esto?",
  ui_story_5009_50091401_176_dialog_content = "Este fue, eh ... nuestro mejor intento de recrear un tamaño pequeño de Soroz.",
  ui_story_5009_50091401_177_dialog_content = "No es perfecto, de ninguna manera... ¡Pero lo llenamos con bocadillos reales!",
  ui_story_5009_50091401_178_dialog_content = "También es nuestra forma de enviarles nuestros mejores deseos, PlayerName!",
  ui_story_5009_50091401_179_dialog_content = "¡Se parece a Soroz! Además, es mucho mejor que cualquier cosa que haya hecho...",
  ui_story_5009_50091401_180_dialog_content = "¿Oh? ¿Significa esto que la marioneta araña del Colossus, la que tiene ojos de rana y alas de murciélago...?",
  ui_story_5009_50091401_181_dialog_content = "Ese fue tu trabajo, PlayerName?",
  ui_story_5009_50091401_182_dialog_content = "¡Basta, Vice! Se supone que los demás no deben saber eso...",
  ui_story_5009_50091401_183_dialog_content = "Asi que PlayerName? ¿Quieres romperlo y tirar los bocadillos dentro?",
  ui_story_5009_50091401_184_dialog_content = "¡Los escojo todos especiadmente para ti!",
  ui_story_5009_50091401_185_dialog_content = "Pero tú y Naroxel trabajaron muy duro en eso, Tweety. Sin mencionar que se parece a Soroz...",
  ui_story_5009_50091401_186_dialog_content = "No creo que pueda romper.",
  ui_story_5009_50091401_187_dialog_content = "P-Pero si no lo debilitas, no será una verdadera celebración, PlayerName...",
  ui_story_5009_50091401_188_dialog_content = "¿Te has olvidado, Tweety?",
  ui_story_5009_50091401_189_dialog_content = "¡Ay! Eso es wight! ¡Dove también hizo esas elegantes luces voladoras!",
  ui_story_5009_50091401_190_dialog_content = "Luces... ¿Voladoras?",
  ui_story_5009_50091401_191_dialog_content = "¿Se refiere a las Linternas de Diente de León que los Celestitas pondrían en marcha durante sus vacaciones?",
  ui_story_5009_50091401_192_dialog_content = "Espera... ¡Dove también hizo esas elegantes luces voladoras!",
  ui_story_5009_50091401_193_dialog_content = "Pregunté antes, pero ¿seguimos hablando de la misma Dove?",
  ui_story_5009_50091401_194_dialog_content = "Dove dijo que había aprendido mucho en Illumina...",
  ui_story_5009_50091401_195_dialog_content = "Y se topó con una guía de instrucciones sobre cómo fabricar linternas de diente de león, así que la tomó sin pensarlo dos veces.",
  ui_story_5009_50091401_196_dialog_content = "¡No puedo esperar para jugar con esas dindas luces!",
  ui_story_5009_50091401_197_dialog_content = "¡salgamos a la platafodma!",
  ui_story_5009_50091401_198_dialog_content = "¡Cuida tus pasos, Tweety! ¡No corras tan rápido!",
  ui_story_5009_50091401_199_dialog_content = "¡Todo bien! Tengo alas, ¿decuerdas?",
  ui_story_5009_50091401_200_dialog_content = "<color=#e8d9bb>Choque...!</color>",
  ui_story_5009_50091401_201_dialog_content = "Ow...",
  ui_story_5009_50091401_202_dialog_content = "¿Estás bien, Tweety? ¡Tuviste una gran caída ahora mismo! ¿Duele?",
  ui_story_5009_50091401_203_dialog_content = "Gracias, Wice ... Ya no duele.",
  ui_story_5009_50091401_204_dialog_content = "Me encontré con una lintedna encendida, eso es todo ... Me quemadon una poco, ¡pero ahora estoy bien!",
  ui_story_5009_50091401_205_dialog_content = "Realmente parecen Dientes de Leónes una vez que los enciendes...",
  ui_story_5009_50091401_206_dialog_content = "PlayerName, cuenta hasta tres, y soltaremos nuestras Dandelion Lanterns al mismo tiempo, ¿de acuerdo?",
  ui_story_5009_50091401_207_dialog_content = "¡Seguro! Uno. Dos. ¡Tres! ¡Despegue!",
  ui_story_5009_50091401_208_dialog_content = "¡Vamos! ¡Vamos!",
  ui_story_5009_50091401_209_dialog_content = "Linternas resplandecientes contra un telón de fondo de innumerables estrellas y la brillante aurora... Una vista poco común que llena de asombro los ojos y el corazón.",
  ui_story_5009_50091401_210_dialog_content = "¡Ha pasado un tiempo desde que te escuché decir algo tan poético, Carleen!",
  ui_story_5009_50091401_211_dialog_content = "Unas hermosas vacaciones como esta no estarían completas sin uno o dos poemas.",
  ui_story_5009_50091401_212_dialog_content = "Deberías haber tomado más lecciones de literatura durante tus estudios en Lumopolis, Vice.",
  ui_story_5009_50091401_213_dialog_content = "Si ese es el caso, un concurso de poesía podría estar en orden.",
  ui_story_5009_50091401_214_dialog_content = "Nunca entendí realmente la literatura ni la poesía, pero ahora mismo...",
  ui_story_5009_50091401_215_dialog_content = "Por un momento, realmente sentí como si las personas que nos dejaron hace mucho tiempo volvieran a estar a mi lado.",
  ui_story_5009_50091401_216_dialog_content = "Y luego, se rieron mientras se daban la vuelta, llevándose mis pensamientos y deseos con ellos...",
  ui_story_5009_50091401_217_dialog_content = "¡Creo que todos deberíamos pedir un deseo!",
  ui_story_5009_50091401_218_dialog_content = "Pero no recuerdo que el Festival de Windland tenga ese tipo de tradición. Qué opinas, PlayerName?",
  ui_story_5009_50091401_219_dialog_content = "¡Miren allí, todos! ¿Mis ojos me juegan una mala pasada o algo vuela hacia nosotros?",
  ui_story_5009_50091401_220_dialog_content = "Como era de esperar, parece que esta publicación estará ocupada en su primer día de operaciones.",
  ui_story_5009_50091401_221_dialog_content = "Entonces esas cosas en el cielo...",
  ui_story_5009_50091401_222_dialog_content = "Creo que esos son mensajeros que llevan cartas de todo el mundo, PlayerName.",
  ui_story_5009_50091401_223_dialog_content = "Nunca me di cuenta de que Unión de Mensajería funcionaba tan rápido...",
  ui_story_5009_50091401_224_dialog_content = "PlayerName acaba de firmar su nombre hace unos minutos, ¡y ya están apareciendo!",
  ui_story_5009_50091401_225_dialog_content = "Luego las cartas que llevan...",
  ui_story_5009_50091401_226_dialog_content = "Precisamente. Son cartas que fueron destinadas a la gente de Eraveil durante los últimos diecisiete años.",
  ui_story_5009_50091401_227_dialog_content = "Y hoy, el día del Festival de Windland...",
  ui_story_5009_50091401_228_dialog_content = "Sus esperanzas, sus inquietudes, sus voces... Finalmente llegarán a su destino.",
  ui_story_5009_50091401_229_dialog_content = "Aun así, nunca hubiera pensado...",
  ui_story_5009_50091401_230_dialog_content = "Que habría tantos mensajeros disponibles para entregar cartas por valor de diecisiete años de una sola vez. Realmente es todo un espectáculo para la vista.",
  ui_story_5009_50091401_231_dialog_content = "Vas a estar ocupado estos próximos días, Tweety.",
  ui_story_5009_50091401_232_dialog_content = "¡Sí! Estoy bien con eso, ¡me gusta mi trabajo!",
  ui_story_5009_50091401_233_dialog_content = "Si tan solo Tweety pudiera venir a trabajar a Illumina...",
  ui_story_5009_50091401_234_dialog_content = "¡Eso sería geniad! ¡Entonces pude ver Dove todos los días!",
  ui_story_5009_50091401_235_dialog_content = "Pero no sé si alguna vez podría tejer el nido o mis compañeros de Northland detrás ...",
  ui_story_5009_50091401_236_dialog_content = "¡Acabo de ver a uno de mis buenos amigos! ¡Viene a entregad las cadtas!",
  ui_story_5009_50091401_237_dialog_content = "¡No tan rápido, Tweety...!",
  ui_story_5009_50091401_238_dialog_content = "<color=#e8d9bb>Choque...!</color>",
  ui_story_5009_50091401_239_dialog_content = "Ow... ¿Qué hay en mi cara? Que produce picor...",
  ui_story_5009_50091401_240_dialog_content = "Aplastaste uno de los Linternas de Diente de León, Tweety... ¡Tu cara está cubierta de pelusa blanca!",
  ui_story_5009_50091401_241_dialog_content = "¡Jajaja! ¡Es tan lindo! ¡Realmente le queda bien!",
  ui_story_5009_50091401_242_dialog_content = "Je...",
  ui_story_5009_50091401_243_dialog_content = "¡Vaya, lo hice! ¡Finadmente hice sonreír a Carween! ¡Jajaja!",
  ui_story_5009_50091401_244_dialog_content = "¡Jajajajaja!",
  ui_story_5009_50091401_245_dialog_content = "Y así fue como pasé mi primer Festival de Windland.",
  ui_story_5009_50091401_246_dialog_content = "Antes del festival...",
  ui_story_5009_50091401_247_dialog_content = "Hubo dolor...",
  ui_story_5009_50091401_248_dialog_content = "Hubo ira...",
  ui_story_5009_50091401_249_dialog_content = "Hubo cambio...",
  ui_story_5009_50091401_250_dialog_content = "Y hubo despedidas...",
  ui_story_5009_50091401_251_dialog_content = "Resulta que hay muchas personas como yo en el mundo.",
  ui_story_5009_50091401_252_dialog_content = "Pero debido a las decisiones que tomamos, recorrimos diferentes caminos en la vida.",
  ui_story_5009_50091401_253_dialog_content = "En los puntos donde nuestros destinos divergen, todo lo que podemos hacer es despedirnos unos de otros...",
  ui_story_5009_50091401_254_dialog_content = "Pero creo que, mientras tomemos nuestras decisiones con la conciencia tranquila, tal vez algún día podamos hacernos amigos.",
  ui_story_5009_50091401_255_dialog_content = "Y que algún día, esos traidores egoístas y malvados también obtendrán lo que merecen.",
  ui_story_5009_50091401_256_dialog_content = "Después de todo lo que he pasado, no puedo evitar sentirme cada vez más agradecido por los amigos que he hecho a lo largo del camino.",
  ui_story_5009_50091401_257_dialog_content = "Especialmente ... en unas vacaciones como estas.",
  ui_story_5009_50091401_258_dialog_content = "Solía creer que las vacaciones eran como cualquier otro día. No entendí el sentido de celebrar nada.",
  ui_story_5009_50091401_259_dialog_content = "Pero ahora, finalmente lo entiendo.",
  ui_story_5009_50091401_260_dialog_content = "En un día especial, para poder rememorar con tus amigos y compartir tus esperanzas para el futuro...",
  ui_story_5009_50091401_261_dialog_content = "Es una experiencia tan cálida y afortunada.",
  ui_story_5009_50091401_262_dialog_content = "Estos últimos días, el Puesto ha recibido cartas de todas partes, a todas horas del día.",
  ui_story_5009_50091401_263_dialog_content = "Aunque la mayoría de ellos no son para mí...",
  ui_story_5009_50091401_264_dialog_content = "Pero Naroxel dice que, como el último de los celestitas, puedo actuar como su único destinatario y abrirlos, si quiero.",
  ui_story_5009_50091401_265_dialog_content = "\"Responder a los deseos de todos es una idea muy romántica\".",
  ui_story_5009_50091401_266_dialog_content = "¿Querrían mis queridos difuntos que siguiera llevando sus pensamientos y sentimientos?",
  ui_story_5009_50091401_267_dialog_content = "Todos dicen que, por supuesto, lo harían...",
  ui_story_5009_50091401_268_dialog_content = "Pero antes de nada de eso, he decidido... Que tengo que enviar mi primera carta de Eraveil.",
  ui_story_5009_50091401_269_dialog_content = "Escribo en mi diario todo el tiempo, pero escribir una carta se siente diferente.",
  ui_story_5009_50091401_270_dialog_content = "Sigo preocupándome de que mi redacción no esté a la altura de la ocasión. Sigo reescribiendo y borrando mis pensamientos...",
  ui_story_5009_50091401_271_dialog_content = "Después de todo, estoy representando a todos los de la especie Celestita al agradecer a todos por todo lo que han hecho por nosotros.",
  ui_story_5009_50091401_272_dialog_content = "Hmm. Me pregunto si han recibido mi carta...",
  ui_story_5009_50091401_273_dialog_content = "La familia Lin en Umbraton..."
}
return config
